"""Error hierarchy shared by every tallybook module."""


class TallybookError(Exception):
    code = "error"

    def __init__(self, message="", *args):
        super().__init__(message, *args)
        self.message = str(message)

    def __str__(self):
        return self.message


class ParseError(TallybookError):
    code = "parse"


class ValidationError(TallybookError):
    code = "validation"


class NotFoundError(TallybookError):
    code = "not_found"


class ConflictError(TallybookError):
    code = "conflict"
"""Exact money: an integer count of minor units plus a currency code."""

import re

from tallybook.currency import CURRENCIES, CurrencyError, currency as _currency
from tallybook.errors import ValidationError


class MoneyError(ValidationError):
    """A malformed amount or an invalid money operation."""


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def round_div(n, d):
    """n / d rounded to the nearest integer, halves away from zero."""
    if not _is_int(n) or not _is_int(d):
        raise MoneyError("round_div needs integers, got %r and %r" % (n, d))
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, got %r" % (d,))
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return q if n >= 0 else -q


def format_minor(minor, currency):
    exp = _currency(currency).exponent
    if not _is_int(minor):
        raise MoneyError("minor units must be an integer, got %r" % (minor,))
    sign = "-" if minor < 0 else ""
    digits = str(abs(minor))
    if exp == 0:
        return sign + digits
    digits = digits.rjust(exp + 1, "0")
    return "%s%s.%s" % (sign, digits[:-exp], digits[-exp:])


_AMOUNT_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def parse_amount(text, currency):
    if not isinstance(text, str):
        raise MoneyError("invalid amount %r: not text" % (text,))
    exp = _currency(currency).exponent
    m = _AMOUNT_RE.fullmatch(text)
    if not m:
        raise MoneyError("invalid amount '%s'" % text)
    sign, whole, frac = m.groups()
    if frac is not None:
        if exp == 0:
            raise MoneyError("invalid amount '%s': %s has no decimals" % (text, currency))
        if len(frac) > exp:
            raise MoneyError("invalid amount '%s': %s has %d decimals" % (text, currency, exp))
    else:
        frac = ""
    value = int(whole) * 10 ** exp + (int(frac.ljust(exp, "0")) if exp else 0)
    return -value if sign == "-" else value


class Money:
    __slots__ = ("_minor", "_currency")

    def __init__(self, minor, currency):
        if not _is_int(minor):
            raise MoneyError("minor units must be an integer, got %r" % (minor,))
        _currency(currency)
        object.__setattr__(self, "_minor", minor)
        object.__setattr__(self, "_currency", currency)

    def __setattr__(self, name, value):
        raise AttributeError("Money is immutable")

    def __delattr__(self, name):
        raise AttributeError("Money is immutable")

    def __reduce__(self):
        return (Money, (self._minor, self._currency))

    @property
    def minor(self):
        return self._minor

    @property
    def currency(self):
        return self._currency

    @property
    def exponent(self):
        return CURRENCIES[self._currency].exponent

    @classmethod
    def zero(cls, currency):
        return cls(0, currency)

    @classmethod
    def of(cls, text, currency):
        return cls(parse_amount(text, currency), currency)

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise MoneyError("invalid money %r: not text" % (text,))
        parts = text.split(" ")
        if len(parts) != 2 or not parts[0] or not parts[1]:
            raise MoneyError("invalid money '%s': expected 'AMOUNT CUR'" % text)
        amount, code = parts
        _currency(code)
        return cls(parse_amount(amount, code), code)

    def amount_str(self):
        return format_minor(self._minor, self._currency)

    def __str__(self):
        return "%s %s" % (self.amount_str(), self._currency)

    def __repr__(self):
        return "Money(%d, '%s')" % (self._minor, self._currency)

    def __eq__(self, other):
        if not isinstance(other, Money):
            return False
        return self._minor == other._minor and self._currency == other._currency

    def __ne__(self, other):
        return not self.__eq__(other)

    def __hash__(self):
        return hash((self._minor, self._currency))

    def _same(self, other, verb):
        if self._currency != other._currency:
            raise MoneyError("cannot %s %s and %s: different currencies" % (verb, self._currency, other._currency))

    def __add__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "add")
        return Money(self._minor + other._minor, self._currency)

    def __radd__(self, other):
        return NotImplemented

    def __sub__(self, other):
        if not isinstance(other, Money):
            return NotImplemented
        self._same(other, "subtract")
        return Money(self._minor - other._minor, self._currency)

    def __rsub__(self, other):
        return NotImplemented

    def __neg__(self):
        return Money(-self._minor, self._currency)

    def __pos__(self):
        return self

    def __abs__(self):
        return Money(abs(self._minor), self._currency)

    def __mul__(self, other):
        if not _is_int(other):
            return NotImplemented
        return Money(self._minor * other, self._currency)

    def __rmul__(self, other):
        if not _is_int(other):
            return NotImplemented
        return Money(self._minor * other, self._currency)

    def _cmp(self, other):
        if not isinstance(other, Money):
            return None
        self._same(other, "compare")
        return True

    def __lt__(self, other):
        if self._cmp(other) is None:
            return NotImplemented
        return self._minor < other._minor

    def __le__(self, other):
        if self._cmp(other) is None:
            return NotImplemented
        return self._minor <= other._minor

    def __gt__(self, other):
        if self._cmp(other) is None:
            return NotImplemented
        return self._minor > other._minor

    def __ge__(self, other):
        if self._cmp(other) is None:
            return NotImplemented
        return self._minor >= other._minor

    def __bool__(self):
        return True

    def is_zero(self):
        return self._minor == 0

    def sign(self):
        return (self._minor > 0) - (self._minor < 0)

    def scale(self, num, den=1):
        if not _is_int(num) or not _is_int(den):
            raise MoneyError("scale needs integers, got %r and %r" % (num, den))
        if den == 0:
            raise MoneyError("scale by a zero denominator")
        if den < 0:
            num, den = -num, -den
        return Money(round_div(self._minor * num, den), self._currency)

    def allocate(self, weights):
        if not isinstance(weights, (list, tuple)) or not weights:
            raise MoneyError("allocate needs a non-empty list of weights")
        for w in weights:
            if not _is_int(w) or w < 0:
                raise MoneyError("invalid weight %r: weights are whole numbers of at least 0" % (w,))
        total = sum(weights)
        if total <= 0:
            raise MoneyError("allocate needs weights with a positive sum")
        amount = abs(self._minor)
        parts = []
        rems = []
        for w in weights:
            q, r = divmod(amount * w, total)
            parts.append(q)
            rems.append(r)
        left = amount - sum(parts)
        order = sorted(range(len(weights)), key=lambda i: (-rems[i], i))
        for i in order[:left]:
            parts[i] += 1
        if self._minor < 0:
            parts = [-p for p in parts]
        return [Money(p, self._currency) for p in parts]
"""Currencies and exchange rates."""

import re
from dataclasses import dataclass
from datetime import date, datetime
from fractions import Fraction

from tallybook.errors import ValidationError


class CurrencyError(ValidationError):
    """An unknown currency, a bad rate or a missing rate."""


@dataclass(frozen=True)
class Currency:
    code: str
    exponent: int
    name: str
    symbol: str


_TABLE = [
    ("USD", 2, "US Dollar", "$"),
    ("EUR", 2, "Euro", "€"),
    ("GBP", 2, "British Pound", "£"),
    ("JPY", 0, "Japanese Yen", "¥"),
    ("CHF", 2, "Swiss Franc", "CHF"),
    ("CAD", 2, "Canadian Dollar", "CA$"),
    ("AUD", 2, "Australian Dollar", "A$"),
    ("KWD", 3, "Kuwaiti Dinar", "KD"),
    ("SEK", 2, "Swedish Krona", "kr"),
    ("INR", 2, "Indian Rupee", "₹"),
    ("NZD", 2, "New Zealand Dollar", "NZ$"),
    ("NOK", 2, "Norwegian Krone", "kr"),
    ("KRW", 0, "South Korean Won", "₩"),
    ("BHD", 3, "Bahraini Dinar", "BD"),
    ("CNY", 2, "Chinese Yuan", "CN¥"),
    ("MXN", 2, "Mexican Peso", "MX$"),
]

CURRENCIES = {code: Currency(code, exp, name, sym) for code, exp, name, sym in _TABLE}


def is_currency(code):
    return isinstance(code, str) and code in CURRENCIES


def currency(code):
    """Return the Currency for a code; CurrencyError when unknown."""
    if isinstance(code, str) and code in CURRENCIES:
        return CURRENCIES[code]
    if isinstance(code, str):
        raise CurrencyError("unknown currency %r" % code)
    raise CurrencyError("unknown currency %r" % (code,))


_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")


def parse_rate_text(text):
    """Check rate text and return it as an exact positive Fraction."""
    if not isinstance(text, str) or not _RATE_RE.fullmatch(text):
        raise CurrencyError("invalid rate %r: expected a positive decimal number" % (text,))
    value = Fraction(text)
    if value <= 0:
        raise CurrencyError("invalid rate %r: must be positive" % (text,))
    return value


def _check_date(on):
    if not isinstance(on, date) or isinstance(on, datetime):
        raise CurrencyError("invalid date %r: expected a datetime.date" % (on,))


def _fmt(d):
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


class RateTable:
    """Exchange rates by day; one unit of src buys `rate` units of dst."""

    def __init__(self):
        self._rates = {}  # (src, dst) -> {date: (Fraction, text)}

    def set(self, src, dst, rate_text, on):
        currency(src)
        currency(dst)
        if src == dst:
            raise CurrencyError("cannot set a rate from %s to itself" % src)
        value = parse_rate_text(rate_text)
        _check_date(on)
        self._rates.setdefault((src, dst), {})[on] = (value, rate_text)

    def text(self, src, dst, on):
        """The rate text stored for exactly that day (or None)."""
        entry = self._rates.get((src, dst), {}).get(on)
        return entry[1] if entry else None

    def _latest(self, src, dst, on):
        table = self._rates.get((src, dst))
        if not table:
            return None
        best = None
        for d in table:
            if d <= on and (best is None or d > best):
                best = d
        return None if best is None else table[best][0]

    def rate(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        if src == dst:
            return Fraction(1)
        direct = self._latest(src, dst, on)
        if direct is not None:
            return direct
        inverse = self._latest(dst, src, on)
        if inverse is not None:
            return 1 / inverse
        raise CurrencyError("no rate %s -> %s on %s" % (src, dst, _fmt(on)))

    def convert(self, money, dst, on):
        from tallybook.money import Money, round_div

        if not isinstance(money, Money):
            raise CurrencyError("cannot convert %r: not a Money" % (money,))
        target = currency(dst)
        _check_date(on)
        if money.currency == dst:
            return money
        r = self.rate(money.currency, dst, on)
        value = money.minor * r * Fraction(10) ** (target.exponent - money.exponent)
        return Money(round_div(value.numerator, value.denominator), dst)

    def entries(self):
        out = []
        for (src, dst), table in self._rates.items():
            for d, (value, _text) in table.items():
                out.append((src, dst, d, value))
        out.sort(key=lambda e: (e[0], e[1], e[2]))
        return out

    def remove(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        table = self._rates.get((src, dst))
        if not table or on not in table:
            raise CurrencyError("no rate %s -> %s set on %s" % (src, dst, _fmt(on)))
        del table[on]
        if not table:
            del self._rates[(src, dst)]

"""Strict dates, month arithmetic and periods."""

import re
from datetime import date, datetime, timedelta

from tallybook.errors import ParseError


class DateError(ParseError):
    """A malformed date, period or date operation."""


_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _is_date(v):
    return isinstance(v, date) and not isinstance(v, datetime)


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date %r: expected text YYYY-MM-DD" % (text,))
    m = _DATE_RE.fullmatch(text)
    if not m:
        raise DateError("invalid date '%s': expected YYYY-MM-DD" % text)
    y, mo, d = (int(g) for g in m.groups())
    try:
        return date(y, mo, d)
    except ValueError:
        raise DateError("invalid date '%s': no such day" % text) from None


def format_date(d):
    if not isinstance(d, date):
        raise DateError("not a date: %r" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def last_day(year, month):
    if not _is_int(year) or not _is_int(month):
        raise DateError("last_day needs integers, got %r and %r" % (year, month))
    if not 1 <= month <= 12:
        raise DateError("invalid month %d" % month)
    if not 1 <= year <= 9999:
        raise DateError("invalid year %d" % year)
    if month == 2:
        return 29 if is_leap(year) else 28
    return 30 if month in (4, 6, 9, 11) else 31


def add_months(d, n):
    if not _is_date(d):
        raise DateError("add_months needs a date, got %r" % (d,))
    if not _is_int(n):
        raise DateError("add_months needs a whole number of months, got %r" % (n,))
    idx = d.year * 12 + (d.month - 1) + n
    y, m = divmod(idx, 12)
    m += 1
    if not 1 <= y <= 9999:
        raise DateError("date out of range: %s moved by %d months" % (format_date(d), n))
    return date(y, m, min(d.day, last_day(y, m)))


def _quarter_start(d):
    return date(d.year, 3 * ((d.month - 1) // 3) + 1, 1)


class Period:
    __slots__ = ("_start", "_end")

    def __init__(self, start, end):
        if not _is_date(start) or not _is_date(end):
            raise DateError("a period needs two dates, got %r and %r" % (start, end))
        if end < start:
            raise DateError("empty period: %s is before %s" % (format_date(end), format_date(start)))
        object.__setattr__(self, "_start", start)
        object.__setattr__(self, "_end", end)

    def __setattr__(self, name, value):
        raise AttributeError("Period is immutable")

    def __reduce__(self):
        return (Period, (self._start, self._end))

    @property
    def start(self):
        return self._start

    @property
    def end(self):
        return self._end

    def __eq__(self, other):
        if not isinstance(other, Period):
            return NotImplemented
        return self._start == other._start and self._end == other._end

    def __hash__(self):
        return hash((self._start, self._end))

    def __repr__(self):
        return "Period(%r, %r)" % (self._start, self._end)

    def contains(self, d):
        if not isinstance(d, date):
            raise DateError("not a date: %r" % (d,))
        if isinstance(d, datetime):
            d = d.date()
        return self._start <= d <= self._end

    @property
    def days(self):
        return (self._end - self._start).days + 1

    def kind(self):
        s, e = self._start, self._end
        if s.day == 1 and s.month == 1 and e.year == s.year and e.month == 12 and e.day == 31:
            return "year"
        if s.day == 1 and e.year == s.year and e.month == s.month and e.day == last_day(e.year, e.month):
            return "month"
        if (s.day == 1 and s.month in (1, 4, 7, 10) and e.year == s.year and e.month == s.month + 2
                and e.day == last_day(e.year, e.month)):
            return "quarter"
        return "range"

    @property
    def label(self):
        k = self.kind()
        s = self._start
        if k == "year":
            return "%04d" % s.year
        if k == "month":
            return "%04d-%02d" % (s.year, s.month)
        if k == "quarter":
            return "%04d-Q%d" % (s.year, (s.month - 1) // 3 + 1)
        return "%s..%s" % (format_date(self._start), format_date(self._end))

    def __str__(self):
        return self.label

    def next(self):
        k = self.kind()
        try:
            if k == "year":
                y = self._start.year + 1
                if y > 9999:
                    raise DateError("no period after %s" % self.label)
                return Period(date(y, 1, 1), date(y, 12, 31))
            if k in ("month", "quarter"):
                n = 1 if k == "month" else 3
                if self._end == date(9999, 12, 31):
                    raise DateError("no period after %s" % self.label)
                s = add_months(self._start, n)
                e = add_months(s, n - 1)
                return Period(s, date(e.year, e.month, last_day(e.year, e.month)))
            s = self._end + timedelta(days=1)
            e = s + timedelta(days=self.days - 1)
            return Period(s, e)
        except OverflowError:
            raise DateError("no period after %s" % self.label) from None

    @classmethod
    def parse(cls, text):
        if not isinstance(text, str):
            raise DateError("invalid period %r" % (text,))
        try:
            if re.fullmatch(r"[0-9]{4}", text):
                y = int(text)
                if y >= 1:
                    return cls(date(y, 1, 1), date(y, 12, 31))
            m = re.fullmatch(r"([0-9]{4})-([0-9]{2})", text)
            if m:
                y, mo = int(m.group(1)), int(m.group(2))
                if y >= 1 and 1 <= mo <= 12:
                    return cls(date(y, mo, 1), date(y, mo, last_day(y, mo)))
            m = re.fullmatch(r"([0-9]{4})-Q([1-4])", text)
            if m:
                y, q = int(m.group(1)), int(m.group(2))
                if y >= 1:
                    sm = 3 * (q - 1) + 1
                    return cls(date(y, sm, 1), date(y, sm + 2, last_day(y, sm + 2)))
            m = re.fullmatch(r"([0-9]{4}-[0-9]{2}-[0-9]{2})\.\.([0-9]{4}-[0-9]{2}-[0-9]{2})", text)
            if m:
                s = parse_date(m.group(1))
                e = parse_date(m.group(2))
                return cls(s, e)
        except DateError:
            pass
        raise DateError("invalid period '%s': expected YYYY, YYYY-MM, YYYY-Qn or YYYY-MM-DD..YYYY-MM-DD" % text)


def _calendar_period(d, step):
    if step == "week":
        s = d - timedelta(days=d.weekday())
        try:
            e = s + timedelta(days=6)
        except OverflowError:
            e = date(9999, 12, 31)
        return Period(s, e)
    if step == "month":
        return Period(date(d.year, d.month, 1), date(d.year, d.month, last_day(d.year, d.month)))
    if step == "quarter":
        s = _quarter_start(d)
        return Period(s, date(s.year, s.month + 2, last_day(s.year, s.month + 2)))
    return Period(date(d.year, 1, 1), date(d.year, 12, 31))


STEPS = ("week", "month", "quarter", "year")


def periods(start, end, step):
    if not _is_date(start) or not _is_date(end):
        raise DateError("periods needs two dates, got %r and %r" % (start, end))
    if not isinstance(step, str) or step not in STEPS:
        raise DateError("unknown step %r: expected week, month, quarter or year" % (step,))
    if end < start:
        raise DateError("end %s is before start %s" % (format_date(end), format_date(start)))
    out = []
    p = _calendar_period(start, step)
    while True:
        out.append(p)
        if p.end >= end:
            break
        p = _calendar_period(p.end + timedelta(days=1), step)
    return out

"""The chart of accounts."""

import re
from datetime import date, datetime

from tallybook.currency import CURRENCIES
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Account


class ChartError(ValidationError):
    def __init__(self, message="", code=None):
        super().__init__(message)
        if code is not None:
            self.code = code


ROOT_TYPES = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = ("asset", "liability", "equity", "income", "expense")

_SEGMENT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def valid_segment(seg):
    return isinstance(seg, str) and _SEGMENT_RE.fullmatch(seg) is not None


def valid_path(text):
    try:
        if not isinstance(text, str) or not text:
            return False
        segs = text.split(":")
        if segs[0] not in ROOT_TYPES:
            return False
        return all(_SEGMENT_RE.fullmatch(s) for s in segs)
    except Exception:
        return False


def _check_path(path):
    if not valid_path(path):
        raise ChartError("invalid account path %r" % (path,))


def parent_path(path):
    _check_path(path)
    if ":" not in path:
        return None
    return path.rsplit(":", 1)[0]


def account_type(path):
    _check_path(path)
    return ROOT_TYPES[path.split(":", 1)[0]]


def path_key(path):
    return path.split(":")


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern %r" % (pattern,))
    segs = pattern.split(":")
    for s in segs:
        if s in ("*", "**"):
            continue
        if not _SEGMENT_RE.fullmatch(s):
            raise ChartError("invalid account pattern %r" % (pattern,))
    return segs


def _match_segs(pat, segs):
    if not pat:
        return not segs
    head = pat[0]
    if head == "**":
        for i in range(1, len(segs) + 1):
            if _match_segs(pat[1:], segs[i:]):
                return True
        return False
    if not segs:
        return False
    if head != "*" and head != segs[0]:
        return False
    return _match_segs(pat[1:], segs[1:])


def path_matches(pattern, path):
    pat = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    if "*" not in pat and "**" not in pat:
        return path == pattern or path.startswith(pattern + ":")
    return _match_segs(pat, path.split(":"))


def _is_date(v):
    return isinstance(v, date) and not isinstance(v, datetime)


class Chart:
    def __init__(self):
        self._accounts = {}
        self._added = set()

    def add(self, path, type=None, currency=None, opened=None, note=""):
        _check_path(path)
        root_type = account_type(path)
        if type is not None:
            if type not in TYPES:
                raise ChartError("invalid account type %r" % (type,))
            if type != root_type:
                raise ChartError("account %s must be of type %s, not %s" % (path, root_type, type))
        if currency is not None and not (isinstance(currency, str) and currency in CURRENCIES):
            raise ChartError("unknown currency %r" % (currency,))
        if opened is not None and not _is_date(opened):
            raise ChartError("invalid opening date %r" % (opened,))
        if not isinstance(note, str):
            raise ChartError("invalid note %r" % (note,))
        if path in self._added:
            raise ChartError("account %s already exists" % path, code="conflict")
        segs = path.split(":")
        for i in range(1, len(segs)):
            parent = ":".join(segs[:i])
            if parent not in self._accounts:
                self._accounts[parent] = Account(parent, ROOT_TYPES[segs[0]])
        acct = self._accounts.get(path)
        if acct is None:
            acct = Account(path, root_type, currency, opened, None, note)
            self._accounts[path] = acct
        else:
            acct.currency = currency
            acct.opened = opened
            acct.note = note
        self._added.add(path)
        return acct

    def was_added(self, path):
        return path in self._added

    def get(self, path):
        if isinstance(path, str) and path in self._accounts:
            return self._accounts[path]
        raise NotFoundError("no such account: %s" % (path,))

    def exists(self, path):
        try:
            return isinstance(path, str) and path in self._accounts
        except Exception:
            return False

    def __contains__(self, path):
        return self.exists(path)

    def accounts(self):
        return [self._accounts[p] for p in sorted(self._accounts, key=path_key)]

    def children(self, path):
        self.get(path)
        depth = path.count(":") + 1
        return [a for a in self.accounts() if a.path.startswith(path + ":") and a.path.count(":") == depth]

    def descendants(self, path):
        self.get(path)
        return [a for a in self.accounts() if a.path.startswith(path + ":")]

    def is_leaf(self, path):
        return not self.children(path)

    def is_open(self, path, on):
        acct = self.get(path)
        if acct.opened is not None and on < acct.opened:
            return False
        if acct.closed is not None and on > acct.closed:
            return False
        return True

    def close(self, path, on):
        acct = self.get(path)
        if not _is_date(on):
            raise ChartError("invalid closing date %r" % (on,))
        if acct.closed is not None:
            raise ChartError("account %s is already closed" % path)
        if acct.opened is not None and on < acct.opened:
            raise ChartError("account %s cannot be closed before it was opened" % path)
        acct.closed = on
        return acct

    def matches(self, pattern):
        _check_pattern(pattern)
        return [a for a in self.accounts() if path_matches(pattern, a.path)]
