"""The ledger: validated transactions and balances."""

import re
from datetime import date, datetime

from tallybook.accounts import Chart
from tallybook.currency import RateTable
from tallybook.errors import NotFoundError, ValidationError
from tallybook.money import Money, format_minor
from tallybook.model import Posting, Transaction


class LedgerError(ValidationError):
    """A transaction the ledger refuses."""


TAG_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


def _is_date(v):
    return isinstance(v, date) and not isinstance(v, datetime)


def _fmt(d):
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def _has_break(text):
    return "\n" in text or "\r" in text


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._next_id = 1

    def __len__(self):
        return len(self._txs)

    # -- validation -------------------------------------------------------
    def _check(self, tx, in_use, keep_id=None):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        if not _is_date(tx.date):
            raise LedgerError("invalid transaction date %r" % (tx.date,))
        if tx.flag not in ("*", "!"):
            raise LedgerError("invalid flag %r: expected * or !" % (tx.flag,))
        for name, value in (("payee", tx.payee), ("narration", tx.narration)):
            if not isinstance(value, str):
                raise LedgerError("%s must be text" % name)
            if _has_break(value):
                raise LedgerError("%s must not contain a line break" % name)
        tags = tx.tags
        if isinstance(tags, str) or not isinstance(tags, (list, tuple, set, frozenset)):
            raise LedgerError("tags must be a list of tag names")
        for t in tags:
            if not isinstance(t, str) or not TAG_RE.fullmatch(t):
                raise LedgerError("invalid tag %r" % (t,))
        postings = tx.postings
        if not isinstance(postings, (list, tuple)):
            raise LedgerError("postings must be a list")
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("not a posting: %r" % (p,))
            if not isinstance(p.account, str):
                raise LedgerError("unknown account %r" % (p.account,))
            if not isinstance(p.note, str) or _has_break(p.note):
                raise LedgerError("a posting note must be text without a line break")
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("invalid amount %r: expected Money" % (p.amount,))
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account %s" % p.account)
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, _fmt(tx.date)))
        missing = [i for i, p in enumerate(postings) if p.amount is None]
        if len(missing) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = {}
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] = sums.get(p.amount.currency, 0) + p.amount.minor
        off = sorted(c for c, v in sums.items() if v != 0)
        new_postings = list(postings)
        if missing:
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            i = missing[0]
            gap = new_postings[i]
            fill = [Posting(gap.account, Money(-sums[c], c), gap.note) for c in off]
            new_postings[i:i + 1] = fill
        elif off:
            parts = ", ".join("%s %s" % (c, format_minor(sums[c], c)) for c in off)
            raise LedgerError("transaction does not balance: %s" % parts)
        for p in new_postings:
            acct = self.chart.get(p.account)
            if acct.currency is not None and p.amount.currency != acct.currency:
                raise LedgerError("account %s only holds %s, not %s" % (p.account, acct.currency, p.amount.currency))
        if keep_id is not None:
            if tx.id is not None and tx.id != keep_id:
                raise LedgerError("transaction id %r does not match %d" % (tx.id, keep_id))
            new_id = keep_id
        elif tx.id is None:
            new_id = None
        else:
            if not isinstance(tx.id, int) or isinstance(tx.id, bool) or tx.id < 1:
                raise LedgerError("invalid transaction id %r" % (tx.id,))
            if tx.id in in_use:
                raise LedgerError("transaction %d already exists" % tx.id)
            new_id = tx.id
        return Transaction(tx.date, tx.payee, tx.narration, new_postings, tuple(sorted(set(tags))), tx.flag, new_id)

    # -- changing ---------------------------------------------------------
    def add(self, tx):
        stored = self._check(tx, self._txs)
        if stored.id is None:
            stored.id = self._next_id
        self._txs[stored.id] = stored
        self._next_id = max(self._next_id, stored.id + 1)
        return stored

    def add_many(self, transactions):
        saved_txs = dict(self._txs)
        saved_next = self._next_id
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs = saved_txs
            self._next_id = saved_next
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        stored = self._check(tx, self._txs, keep_id=id)
        self._txs[id] = stored
        return stored

    def _load(self, tx):
        """Insert a stored transaction as it is (used when reloading a book)."""
        self._txs[tx.id] = tx
        self._next_id = max(self._next_id, tx.id + 1)

    # -- reading ----------------------------------------------------------
    def get(self, id):
        try:
            return self._txs[id]
        except (KeyError, TypeError):
            raise NotFoundError("no transaction %s" % (id,)) from None

    def remove(self, id):
        tx = self.get(id)
        del self._txs[id]
        return tx

    def transactions(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def postings(self):
        for tx in self.transactions():
            for p in tx.postings:
                yield tx, p

    # -- balances ---------------------------------------------------------
    def _raw(self, as_of):
        out = {}
        for tx in self._txs.values():
            if as_of is not None and tx.date > as_of:
                continue
            for p in tx.postings:
                acc = out.setdefault(p.account, {})
                acc[p.amount.currency] = acc.get(p.amount.currency, 0) + p.amount.minor
        return out

    @staticmethod
    def _clean(raw):
        out = {}
        for acct, cur in raw.items():
            c = {k: v for k, v in sorted(cur.items()) if v != 0}
            if c:
                out[acct] = c
        return dict(sorted(out.items()))

    def balances(self, as_of=None):
        return self._clean(self._raw(as_of))

    def rollup_balances(self, as_of=None):
        raw = self._raw(as_of)
        out = {}
        for acct, cur in raw.items():
            segs = acct.split(":")
            for i in range(1, len(segs) + 1):
                target = out.setdefault(":".join(segs[:i]), {})
                for c, v in cur.items():
                    target[c] = target.get(c, 0) + v
        return self._clean(out)

    def balance(self, account, as_of=None, currency=None, rollup=True):
        if not self.chart.exists(account):
            raise NotFoundError("no such account: %s" % (account,))
        totals = {}
        for tx in self._txs.values():
            if as_of is not None and tx.date > as_of:
                continue
            for p in tx.postings:
                if p.account == account or (rollup and p.account.startswith(account + ":")):
                    totals[p.amount.currency] = totals.get(p.amount.currency, 0) + p.amount.minor
        if currency is not None:
            return Money(totals.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in sorted(totals.items()) if v != 0}

"""The chart of accounts."""

import re
from datetime import date, datetime

from tallybook.currency import CURRENCIES
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Account


class ChartError(ValidationError):
    def __init__(self, message="", code=None):
        super().__init__(message)
        if code is not None:
            self.code = code


ROOT_TYPES = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = ("asset", "liability", "equity", "income", "expense")

_SEGMENT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def valid_segment(seg):
    return isinstance(seg, str) and _SEGMENT_RE.fullmatch(seg) is not None


def valid_path(text):
    try:
        if not isinstance(text, str) or not text:
            return False
        segs = text.split(":")
        if segs[0] not in ROOT_TYPES:
            return False
        return all(_SEGMENT_RE.fullmatch(s) for s in segs)
    except Exception:
        return False


def _check_path(path):
    if not valid_path(path):
        raise ChartError("invalid account path %r" % (path,))


def parent_path(path):
    _check_path(path)
    if ":" not in path:
        return None
    return path.rsplit(":", 1)[0]


def account_type(path):
    _check_path(path)
    return ROOT_TYPES[path.split(":", 1)[0]]


def path_key(path):
    return path.split(":")


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern %r" % (pattern,))
    segs = pattern.split(":")
    for s in segs:
        if s in ("*", "**"):
            continue
        if not _SEGMENT_RE.fullmatch(s):
            raise ChartError("invalid account pattern %r" % (pattern,))
    return segs


def _match_segs(pat, segs):
    if not pat:
        return not segs
    head = pat[0]
    if head == "**":
        for i in range(1, len(segs) + 1):
            if _match_segs(pat[1:], segs[i:]):
                return True
        return False
    if not segs:
        return False
    if head != "*" and head != segs[0]:
        return False
    return _match_segs(pat[1:], segs[1:])


def path_matches(pattern, path):
    pat = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    if "*" not in pat and "**" not in pat:
        return path == pattern or path.startswith(pattern + ":")
    return _match_segs(pat, path.split(":"))


def _is_date(v):
    return isinstance(v, date) and not isinstance(v, datetime)


class Chart:
    def __init__(self):
        self._accounts = {}
        self._added = set()

    def add(self, path, type=None, currency=None, opened=None, note=""):
        _check_path(path)
        root_type = account_type(path)
        if type is not None:
            if type not in TYPES:
                raise ChartError("invalid account type %r" % (type,))
            if type != root_type:
                raise ChartError("account %s must be of type %s, not %s" % (path, root_type, type))
        if currency is not None and not (isinstance(currency, str) and currency in CURRENCIES):
            raise ChartError("unknown currency %r" % (currency,))
        if opened is not None and not _is_date(opened):
            raise ChartError("invalid opening date %r" % (opened,))
        if not isinstance(note, str):
            raise ChartError("invalid note %r" % (note,))
        if path in self._added:
            raise ChartError("account %s already exists" % path, code="conflict")
        segs = path.split(":")
        for i in range(1, len(segs)):
            parent = ":".join(segs[:i])
            if parent not in self._accounts:
                self._accounts[parent] = Account(parent, ROOT_TYPES[segs[0]])
        acct = self._accounts.get(path)
        if acct is None:
            acct = Account(path, root_type, currency, opened, None, note)
            self._accounts[path] = acct
        else:
            acct.currency = currency
            acct.opened = opened
            acct.note = note
        self._added.add(path)
        return acct

    def was_added(self, path):
        return path in self._added

    def get(self, path):
        if isinstance(path, str) and path in self._accounts:
            return self._accounts[path]
        raise NotFoundError("no such account: %s" % (path,))

    def exists(self, path):
        try:
            return isinstance(path, str) and path in self._accounts
        except Exception:
            return False

    def __contains__(self, path):
        return self.exists(path)

    def accounts(self):
        return [self._accounts[p] for p in sorted(self._accounts, key=path_key)]

    def children(self, path):
        self.get(path)
        depth = path.count(":") + 1
        return [a for a in self.accounts() if a.path.startswith(path + ":") and a.path.count(":") == depth]

    def descendants(self, path):
        self.get(path)
        return [a for a in self.accounts() if a.path.startswith(path + ":")]

    def is_leaf(self, path):
        return not self.children(path)

    def is_open(self, path, on):
        acct = self.get(path)
        if acct.opened is not None and on < acct.opened:
            return False
        if acct.closed is not None and on > acct.closed:
            return False
        return True

    def close(self, path, on):
        acct = self.get(path)
        if not _is_date(on):
            raise ChartError("invalid closing date %r" % (on,))
        if acct.closed is not None:
            raise ChartError("account %s is already closed" % path)
        if acct.opened is not None and on < acct.opened:
            raise ChartError("account %s cannot be closed before it was opened" % path)
        acct.closed = on
        return acct

    def matches(self, pattern):
        _check_pattern(pattern)
        return [a for a in self.accounts() if path_matches(pattern, a.path)]
