            new_id = keep_id
        elif tx.id is None:
            new_id = None
        else:
            if not isinstance(tx.id, int) or isinstance(tx.id, bool) or tx.id < 1:
                raise LedgerError("invalid transaction id %r" % (tx.id,))
            if tx.id in in_use:
                raise LedgerError("transaction %d already exists" % tx.id)
