    # -- balances ---------------------------------------------------------
    def _raw(self, as_of):
        out = {}
        for tx in self._txs.values():
            if as_of is not None and tx.date > as_of:
                continue
            for p in tx.postings:
                acc = out.setdefault(p.account, {})
                acc[p.amount.currency] = acc.get(p.amount.currency, 0) + p.amount.minor
        return out

    @staticmethod
    def _clean(raw):
        out = {}
        for acct, cur in raw.items():
            c = {k: v for k, v in sorted(cur.items()) if v != 0}
            if c:
                out[acct] = c
        return dict(sorted(out.items()))

    def balances(self, as_of=None):
        return self._clean(self._raw(as_of))

    def rollup_balances(self, as_of=None):
        raw = self._raw(as_of)
        out = {}
        for acct, cur in raw.items():
            segs = acct.split(":")
            for i in range(1, len(segs) + 1):
                target = out.setdefault(":".join(segs[:i]), {})
                for c, v in cur.items():
                    target[c] = target.get(c, 0) + v
        return self._clean(out)

    def balance(self, account, as_of=None, currency=None, rollup=True):
        if not self.chart.exists(account):
            raise NotFoundError("no such account: %s" % (account,))
        totals = {}
        for tx in self._txs.values():
            if as_of is not None and tx.date > as_of:
                continue
            for p in tx.postings:
                if p.account == account or (rollup and p.account.startswith(account + ":")):
                    totals[p.amount.currency] = totals.get(p.amount.currency, 0) + p.amount.minor
        if currency is not None:
            return Money(totals.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in sorted(totals.items()) if v != 0}

"""The plain-text journal format."""

import re
from dataclasses import dataclass, field
from typing import List

from tallybook.accounts import ROOT_TYPES, valid_path
from tallybook.currency import CURRENCIES, CurrencyError, parse_rate_text
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ParseError
from tallybook.ledger import TAG_RE, Ledger
from tallybook.model import Account, Posting, Transaction
from tallybook.money import Money, MoneyError, parse_amount


class JournalError(ParseError):
    def __init__(self, line, description):
        super().__init__("line %d: %s" % (line, description))
        self.line = line


@dataclass
class Journal:
    accounts: List[Account] = field(default_factory=list)
    rates: list = field(default_factory=list)
    transactions: List[Transaction] = field(default_factory=list)

    def to_ledger(self):
        ledger = Ledger()
        for a in self.accounts:
            ledger.chart.add(a.path, a.type, a.currency, a.opened, a.note)
            if a.closed is not None:
                ledger.chart.close(a.path, a.closed)
        for src, dst, on, text in self.rates:
            ledger.rates.set(src, dst, text, on)
        for tx in self.transactions:
            ledger.add(tx)
        return ledger


# -- reading ------------------------------------------------------------------

_WS = " \t"


def _tokenize(line, lineno):
    """Split a line into tokens (text, quoted) and a trailing ';' comment."""
    tokens = []
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if c in _WS:
            i += 1
            continue
        if c == ";":
            return tokens, line[i + 1:]
        if c == '"':
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise JournalError(lineno, "missing closing quote")
                c = line[i]
                if c == "\\":
                    if i + 1 < n and line[i + 1] in '"\\':
                        buf.append(line[i + 1])
                        i += 2
                        continue
                    raise JournalError(lineno, "invalid backslash escape in quoted text")
                if c == '"':
                    i += 1
                    break
                buf.append(c)
                i += 1
            if i < n and line[i] not in _WS and line[i] != ";":
                raise JournalError(lineno, "unexpected text after a closing quote")
            tokens.append(("".join(buf), True))
            continue
        j = i
        while j < n and line[j] not in _WS and line[j] != ";":
            j += 1
        tokens.append((line[i:j], False))
        i = j
    return tokens, None


def _date(tok, lineno):
    if tok[1]:
        raise JournalError(lineno, "expected a date, not quoted text")
    try:
        return parse_date(tok[0])
    except DateError:
        raise JournalError(lineno, "invalid date '%s'" % tok[0]) from None


def _word(tok, lineno, what):
    if tok[1]:
        raise JournalError(lineno, "expected %s, not quoted text" % what)
    return tok[0]


def _currency_code(tok, lineno):
    code = _word(tok, lineno, "a currency code")
    if code not in CURRENCIES:
        raise JournalError(lineno, "unknown currency '%s'" % code)
    return code


def _account_path(tok, lineno):
    path = _word(tok, lineno, "an account")
    if not valid_path(path):
        raise JournalError(lineno, "invalid account '%s'" % path)
    return path


def _parse_account_line(tokens, lineno):
    if len(tokens) < 2:
        raise JournalError(lineno, "account line needs an account path")
    path = _account_path(tokens[1], lineno)
    rest = tokens[2:]
    cur = opened = closed = None
    note = ""
    i = 0
    if i < len(rest) and not rest[i][1] and rest[i][0] not in ("open", "close"):
        cur = _currency_code(rest[i], lineno)
        i += 1
    if i < len(rest) and rest[i] == ("open", False):
        if i + 1 >= len(rest):
            raise JournalError(lineno, "open needs a date")
        opened = _date(rest[i + 1], lineno)
        i += 2
    if i < len(rest) and rest[i] == ("close", False):
        if i + 1 >= len(rest):
            raise JournalError(lineno, "close needs a date")
        closed = _date(rest[i + 1], lineno)
        i += 2
    if i < len(rest) and rest[i][1]:
        note = rest[i][0]
        i += 1
    if i < len(rest):
        raise JournalError(lineno, "unexpected '%s' on account line" % rest[i][0])
    if opened is not None and closed is not None and closed < opened:
        raise JournalError(lineno, "account %s is closed before it is opened" % path)
    return Account(path, ROOT_TYPES[path.split(":")[0]], cur, opened, closed, note)


def _parse_rate_line(tokens, lineno):
    if len(tokens) != 5:
        raise JournalError(lineno, "rate line must be: rate DATE FROM TO RATE")
    on = _date(tokens[1], lineno)
    src = _currency_code(tokens[2], lineno)
    dst = _currency_code(tokens[3], lineno)
    if src == dst:
        raise JournalError(lineno, "rate needs two different currencies")
    text = _word(tokens[4], lineno, "a rate")
    try:
        parse_rate_text(text)
    except CurrencyError:
        raise JournalError(lineno, "invalid rate '%s'" % text) from None
    return (src, dst, on, text)


def _parse_tx_line(tokens, lineno):
    on = _date(tokens[0], lineno)
    i = 1
    flag = "*"
    if i < len(tokens) and not tokens[i][1] and tokens[i][0] in ("*", "!"):
        flag = tokens[i][0]
        i += 1
    if i >= len(tokens) or not tokens[i][1]:
        raise JournalError(lineno, "transaction needs a quoted payee")
    payee = tokens[i][0]
    i += 1
    narration = ""
    if i < len(tokens) and tokens[i][1]:
        narration = tokens[i][0]
        i += 1
    tags = set()
    while i < len(tokens):
        text, quoted = tokens[i]
        if quoted or not text.startswith("#") or not TAG_RE.fullmatch(text[1:]):
            raise JournalError(lineno, "unexpected '%s' on transaction line" % text)
        tags.add(text[1:])
        i += 1
    return Transaction(on, payee, narration, [], tuple(sorted(tags)), flag, None)


def _parse_posting(tokens, comment, lineno):
    if not tokens:
        raise JournalError(lineno, "posting needs an account")
    account = _account_path(tokens[0], lineno)
    note = comment.strip(" \t") if comment is not None else ""
    if len(tokens) == 1:
        return Posting(account, None, note)
    if len(tokens) == 2:
        raise JournalError(lineno, "amount needs a currency")
    if len(tokens) > 3:
        raise JournalError(lineno, "unexpected '%s' on posting line" % tokens[3][0])
    amount = _word(tokens[1], lineno, "an amount")
    code = _currency_code(tokens[2], lineno)
    try:
        minor = parse_amount(amount, code)
    except MoneyError:
        raise JournalError(lineno, "invalid amount '%s'" % amount) from None
    return Posting(account, Money(minor, code), note)


def parse_journal(text):
    if not isinstance(text, str):
        raise JournalError(1, "journal must be text")
    if text.startswith("﻿"):
        text = text[1:]
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    journal = Journal()
    declared = set()
    current = None
    for idx, raw in enumerate(lines):
        lineno = idx + 1
        line = raw[:-1] if raw.endswith("\r") else raw
        stripped = line.strip(_WS)
        if not stripped:
            current = None
            continue
        if stripped[0] in ";#":
            continue
        indented = line[0] in _WS
        tokens, comment = _tokenize(line, lineno)
        if indented:
            if current is None:
                raise JournalError(lineno, "indented line outside a transaction")
            current.postings.append(_parse_posting(tokens, comment, lineno))
            continue
        current = None
        head = tokens[0]
        if head == ("account", False):
            acct = _parse_account_line(tokens, lineno)
            if acct.path in declared:
                raise JournalError(lineno, "account %s declared twice" % acct.path)
            declared.add(acct.path)
            journal.accounts.append(acct)
        elif head == ("rate", False):
            journal.rates.append(_parse_rate_line(tokens, lineno))
        elif not head[1] and re.match(r"[0-9]", head[0]):
            current = _parse_tx_line(tokens, lineno)
            journal.transactions.append(current)
        else:
            raise JournalError(lineno, "unexpected '%s'" % head[0])
    return journal


# -- writing ------------------------------------------------------------------

def _quote(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def _format_account(a):
    parts = ["account", a.path]
    if a.currency:
        parts.append(a.currency)
    if a.opened is not None:
        parts += ["open", format_date(a.opened)]
    if a.closed is not None:
        parts += ["close", format_date(a.closed)]
    if a.note:
        parts.append(_quote(a.note))
    return " ".join(parts)


def format_transaction(tx):
    head = "%s %s %s" % (format_date(tx.date), tx.flag, _quote(tx.payee))
    if tx.narration:
        head += " " + _quote(tx.narration)
    for t in sorted(set(tx.tags)):
        head += " #" + t
    lines = [head]
    with_amount = [p for p in tx.postings if p.amount is not None]
    aw = max((len(p.account) for p in with_amount), default=0)
    nw = max((len(p.amount.amount_str()) for p in with_amount), default=0)
    for p in tx.postings:
        if p.amount is None:
            line = "  " + p.account
        else:
            line = "  %s  %s %s" % (p.account.ljust(aw), p.amount.amount_str().rjust(nw), p.amount.currency)
        if p.note:
            line += "  ; " + p.note
        lines.append(line.rstrip(" "))
    return "\n".join(lines) + "\n"


def format_journal(journal):
    groups = []
    if journal.accounts:
        groups.append("".join(_format_account(a) + "\n" for a in journal.accounts))
    if journal.rates:
        groups.append("".join("rate %s %s %s %s\n" % (format_date(on), src, dst, text)
                              for src, dst, on, text in journal.rates))
    if journal.transactions:
        groups.append("\n".join(format_transaction(tx) for tx in journal.transactions))
    return "\n".join(groups)

"""The query language for finding transactions."""

import re
from fractions import Fraction

from tallybook.currency import CURRENCIES
from tallybook.dates import DateError, Period, parse_date
from tallybook.errors import ParseError


class QueryError(ParseError):
    def __init__(self, description, position):
        super().__init__("%s at position %d" % (description, position))
        self.position = position


_OPS = ("<=", ">=", "!=", "<", ">", "=")
_NAME_RE = re.compile(r"[A-Za-z_]+")
_PART_RE = re.compile(r"[A-Za-z0-9_-]+")
_NUM_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_STOP = " ()"


def _compare(a, op, b):
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    if op == ">=":
        return a >= b
    if op == "=":
        return a == b
    return a != b


# -- nodes --------------------------------------------------------------------

class _Node:
    def ev(self, tx, p):
        raise NotImplementedError


class _And(_Node):
    def __init__(self, a, b):
        self.a, self.b = a, b

    def ev(self, tx, p):
        return self.a.ev(tx, p) and self.b.ev(tx, p)


class _Or(_Node):
    def __init__(self, a, b):
        self.a, self.b = a, b

    def ev(self, tx, p):
        return self.a.ev(tx, p) or self.b.ev(tx, p)


class _Not(_Node):
    def __init__(self, a):
        self.a = a

    def ev(self, tx, p):
        return not self.a.ev(tx, p)


class _Func(_Node):
    def __init__(self, fn):
        self.fn = fn

    def ev(self, tx, p):
        return self.fn(tx, p)


def _contains(hay, needle):
    return isinstance(hay, str) and needle.lower() in hay.lower()


def account_pattern_matches(parts, path):
    segs = path.split(":")

    def full(pi, si, end):
        if pi == len(parts):
            return si == end
        part = parts[pi]
        if part == "**":
            return any(full(pi + 1, k, end) for k in range(si, end + 1))
        if si >= end:
            return False
        if part != "*" and part != segs[si]:
            return False
        return full(pi + 1, si + 1, end)

    return any(full(0, 0, k) for k in range(len(segs) + 1))


# -- lexer --------------------------------------------------------------------

class _Tok:
    def __init__(self, kind, pos, node=None):
        self.kind = kind  # 'term', 'and', 'or', 'not', '(', ')'
        self.pos = pos
        self.node = node


class _Lexer:
    def __init__(self, text, chart):
        self.text = text
        self.chart = chart

    def quoted(self, i):
        """Read a quoted string starting at i (the quote); return (value, end)."""
        t = self.text
        j = i + 1
        buf = []
        while True:
            if j >= len(t):
                raise QueryError("unterminated quote", i + 1)
            c = t[j]
            if c == "\\" and j + 1 < len(t) and t[j + 1] in '"\\':
                buf.append(t[j + 1])
                j += 2
                continue
            if c == '"':
                j += 1
                break
            buf.append(c)
            j += 1
        if j < len(t) and t[j] not in _STOP:
            raise QueryError("unexpected text after closing quote", j + 1)
        return "".join(buf), j

    def bare(self, i):
        t = self.text
        j = i
        while j < len(t) and t[j] not in _STOP:
            j += 1
        return t[i:j], j

    def tokens(self):
        t = self.text
        out = []
        i = 0
        while i < len(t):
            c = t[i]
            if c == " ":
                i += 1
                continue
            if c in "()":
                out.append(_Tok(c, i + 1))
                i += 1
                continue
            if c == '"':
                value, j = self.quoted(i)
                if value == "":
                    raise QueryError("empty quotes", i + 1)
                out.append(_Tok("term", i + 1, self.text_term(value)))
                i = j
                continue
            m = _NAME_RE.match(t, i)
            if m:
                name_end = m.end()
                if name_end < len(t) and t[name_end] == ":":
                    tok, i = self.colon_term(i, m.group(0), name_end + 1)
                    out.append(tok)
                    continue
                k = name_end
                while k < len(t) and t[k] == " ":
                    k += 1
                op = next((o for o in _OPS if t.startswith(o, k)), None)
                if op is not None:
                    tok, i = self.cmp_term(i, m.group(0), k + len(op))
                    out.append(tok)
                    continue
            word, j = self.bare(i)
            low = word.lower()
            if low in ("and", "or", "not"):
                out.append(_Tok(low, i + 1))
            else:
                out.append(_Tok("term", i + 1, self.text_term(word)))
            i = j
        return out

    @staticmethod
    def text_term(value):
        return _Func(lambda tx, p: _contains(tx.payee, value) or _contains(tx.narration, value))

    def colon_term(self, start, name, i):
        t = self.text
        pos = start + 1
        lname = name.lower()
        if lname not in ("payee", "narration", "tag", "date", "flag", "id", "account"):
            raise QueryError("unknown name '%s'" % name, pos)
        if i < len(t) and t[i] == '"':
            value, j = self.quoted(i)
            if value == "":
                raise QueryError("empty quotes", pos)
        else:
            value, j = self.bare(i)
            if value == "":
                raise QueryError("missing value for '%s'" % name, pos)
        return _Tok("term", pos, self.make_colon(lname, value, pos)), j

    def make_colon(self, name, value, pos):
        if name == "payee":
            return _Func(lambda tx, p: _contains(tx.payee, value))
        if name == "narration":
            return _Func(lambda tx, p: _contains(tx.narration, value))
        if name == "tag":
            tag = value.lower()
            return _Func(lambda tx, p: tag in (tx.tags or ()))
        if name == "date":
            try:
                period = Period.parse(value)
            except DateError:
                raise QueryError("invalid period '%s'" % value, pos) from None
            return _Func(lambda tx, p: period.start <= tx.date <= period.end)
        if name == "flag":
            if value not in ("*", "!"):
                raise QueryError("invalid flag '%s'" % value, pos)
            return _Func(lambda tx, p: tx.flag == value)
        if name == "id":
            if not re.fullmatch(r"[0-9]+", value):
                raise QueryError("invalid id '%s'" % value, pos)
            n = int(value)
            return _Func(lambda tx, p: tx.id is not None and tx.id == n)
        # account
        parts = value.split(":")
        for part in parts:
            if part not in ("*", "**") and not _PART_RE.fullmatch(part):
                raise QueryError("invalid account pattern '%s'" % value, pos)
        if self.chart is not None:
            if not any(account_pattern_matches(parts, a.path) for a in self.chart.accounts()):
                raise QueryError("no account matches 'account:%s'" % value, pos)
        return _Func(lambda tx, p: p is not None and isinstance(p.account, str)
                     and account_pattern_matches(parts, p.account))

    def cmp_term(self, start, name, i):
        t = self.text
        pos = start + 1
        lname = name.lower()
        op = None
        k = start + len(name)
        while t[k] == " ":
            k += 1
        op = next(o for o in _OPS if t.startswith(o, k))
        if lname not in ("date", "amount"):
            raise QueryError("unknown name '%s'" % name, pos)
        while i < len(t) and t[i] == " ":
            i += 1
        value, j = self.bare(i)
        if value == "":
            raise QueryError("missing value for '%s'" % name, pos)
        if lname == "date":
            try:
                day = parse_date(value)
            except DateError:
                raise QueryError("invalid date '%s'" % value, pos) from None
            return _Tok("term", pos, _Func(lambda tx, p: _compare(tx.date, op, day))), j
        m = _NUM_RE.fullmatch(value)
        if not m or (m.group(2) and (not re.fullmatch(r"[A-Z]{3}", m.group(2)) or m.group(2) not in CURRENCIES)):
            raise QueryError("invalid amount '%s'" % value, pos)
        number = Fraction(m.group(1))
        cur = m.group(2) or None

        def fn(tx, p):
            if p is None or p.amount is None:
                return False
            if cur is not None and p.amount.currency != cur:
                return False
            v = Fraction(p.amount.minor, 10 ** p.amount.exponent)
            return _compare(v, op, number)

        return _Tok("term", pos, _Func(fn)), j


# -- parser -------------------------------------------------------------------

class _Parser:
    def __init__(self, tokens, end_pos):
        self.toks = tokens
        self.i = 0
        self.end_pos = end_pos

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None

    def where(self):
        tok = self.peek()
        return tok.pos if tok else self.end_pos

    def parse(self):
        node = self.or_expr()
        tok = self.peek()
        if tok is not None:
            raise QueryError("unmatched ')'" if tok.kind == ")" else "unexpected '%s'" % tok.kind, tok.pos)
        return node

    def or_expr(self):
        node = self.and_expr()
        while self.peek() is not None and self.peek().kind == "or":
            self.i += 1
            node = _Or(node, self.and_expr())
        return node

    def and_expr(self):
        node = self.not_expr()
        while True:
            tok = self.peek()
            if tok is None:
                return node
            if tok.kind == "and":
                self.i += 1
                node = _And(node, self.not_expr())
            elif tok.kind in ("term", "not", "("):
                node = _And(node, self.not_expr())
            else:
                return node

    def not_expr(self):
        tok = self.peek()
        if tok is not None and tok.kind == "not":
            self.i += 1
            return _Not(self.not_expr())
        return self.primary()

    def primary(self):
        tok = self.peek()
        if tok is None:
            raise QueryError("a term was expected", self.end_pos)
        if tok.kind == "term":
            self.i += 1
            return tok.node
        if tok.kind == "(":
            self.i += 1
            node = self.or_expr()
            close = self.peek()
            if close is None:
                raise QueryError("unclosed '('", tok.pos)
            if close.kind != ")":
                raise QueryError("expected ')'", close.pos)
            self.i += 1
            return node
        raise QueryError("a term was expected, not '%s'" % tok.kind, tok.pos)


class Query:
    def __init__(self, text, node):
        self.text = text
        self._node = node

    @property
    def is_empty(self):
        return self._node is None

    def __repr__(self):
        return "Query(%r)" % (self.text,)

    def _ok(self, tx, p):
        return self._node.ev(tx, p)

    def matches(self, tx):
        if self._node is None:
            return True
        return any(self._node.ev(tx, p) for p in tx.postings)

    def matching_postings(self, tx):
        if self._node is None:
            return list(tx.postings)
        return [p for p in tx.postings if self._node.ev(tx, p)]


def parse_query(text, chart=None):
    if not isinstance(text, str):
        raise QueryError("query must be text", 1)
    if text.strip(" ") == "":
        return Query(text, None)
    tokens = _Lexer(text, chart).tokens()
    node = _Parser(tokens, len(text) + 1).parse()
    return Query(text, node)


def select(transactions, q):
    if not isinstance(q, Query):
        q = parse_query(q)
    return [tx for tx in transactions if q.matches(tx)]

"""The query language for finding transactions."""

import re
from fractions import Fraction

from tallybook.currency import CURRENCIES
from tallybook.dates import DateError, Period, parse_date
from tallybook.errors import ParseError


class QueryError(ParseError):
    def __init__(self, description, position):
        super().__init__("%s at position %d" % (description, position))
        self.position = position


_OPS = ("<=", ">=", "!=", "<", ">", "=")
_NAME_RE = re.compile(r"[A-Za-z_]+")
_PART_RE = re.compile(r"[A-Za-z0-9_-]+")
_NUM_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Za-z]*)")
_STOP = " ()"


def _compare(a, op, b):
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    if op == ">=":
        return a >= b
    if op == "=":
        return a == b
    return a != b


# -- nodes --------------------------------------------------------------------

class _Node:
    def ev(self, tx, p):
        raise NotImplementedError


class _And(_Node):
    def __init__(self, a, b):
        self.a, self.b = a, b

    def ev(self, tx, p):
        return self.a.ev(tx, p) and self.b.ev(tx, p)


class _Or(_Node):
    def __init__(self, a, b):
        self.a, self.b = a, b

    def ev(self, tx, p):
        return self.a.ev(tx, p) or self.b.ev(tx, p)


class _Not(_Node):
    def __init__(self, a):
        self.a = a

    def ev(self, tx, p):
        return not self.a.ev(tx, p)


class _Func(_Node):
    def __init__(self, fn):
        self.fn = fn

    def ev(self, tx, p):
        return self.fn(tx, p)


def _contains(hay, needle):
    return isinstance(hay, str) and needle.lower() in hay.lower()


def account_pattern_matches(parts, path):
    segs = path.split(":")

    def full(pi, si, end):
        if pi == len(parts):
            return si == end
        part = parts[pi]
        if part == "**":
            return any(full(pi + 1, k, end) for k in range(si, end + 1))
        if si >= end:
            return False
        if part != "*" and part != segs[si]:
            return False
        return full(pi + 1, si + 1, end)

    return any(full(0, 0, k) for k in range(len(segs) + 1))


# -- lexer --------------------------------------------------------------------

class _Tok:
    def __init__(self, kind, pos, node=None):
        self.kind = kind  # 'term', 'and', 'or', 'not', '(', ')'
        self.pos = pos
        self.node = node


class _Lexer:
    def __init__(self, text, chart):
        self.text = text
        self.chart = chart

    def quoted(self, i):
        """Read a quoted string starting at i (the quote); return (value, end)."""
        t = self.text
        j = i + 1
        buf = []
        while True:
            if j >= len(t):
                raise QueryError("unterminated quote", i + 1)
            c = t[j]
            if c == "\\" and j + 1 < len(t) and t[j + 1] in '"\\':
                buf.append(t[j + 1])
                j += 2
                continue
            if c == '"':
                j += 1
                break
            buf.append(c)
            j += 1
        if j < len(t) and t[j] not in _STOP:
            raise QueryError("unexpected text after closing quote", j + 1)
        return "".join(buf), j

    def bare(self, i):
        t = self.text
        j = i
        while j < len(t) and t[j] not in _STOP:
            j += 1
        return t[i:j], j

    def tokens(self):
        t = self.text
        out = []
        i = 0
        while i < len(t):
            c = t[i]
            if c == " ":
                i += 1
                continue
            if c in "()":
                out.append(_Tok(c, i + 1))
                i += 1
                continue
            if c == '"':
                value, j = self.quoted(i)
                if value == "":
                    raise QueryError("empty quotes", i + 1)
                out.append(_Tok("term", i + 1, self.text_term(value)))
                i = j
                continue
            m = _NAME_RE.match(t, i)
            if m:
                name_end = m.end()
                if name_end < len(t) and t[name_end] == ":":
                    tok, i = self.colon_term(i, m.group(0), name_end + 1)
                    out.append(tok)
                    continue
                k = name_end
                while k < len(t) and t[k] == " ":
                    k += 1
                op = next((o for o in _OPS if t.startswith(o, k)), None)
                if op is not None:
                    tok, i = self.cmp_term(i, m.group(0), k + len(op))
                    out.append(tok)
                    continue
            word, j = self.bare(i)
            low = word.lower()
            if low in ("and", "or", "not"):
                out.append(_Tok(low, i + 1))
            else:
                out.append(_Tok("term", i + 1, self.text_term(word)))
            i = j
        return out

    @staticmethod
    def text_term(value):
        return _Func(lambda tx, p: _contains(tx.payee, value) or _contains(tx.narration, value))

    def colon_term(self, start, name, i):
        t = self.text
        pos = start + 1
        lname = name.lower()
        if lname not in ("payee", "narration", "tag", "date", "flag", "id", "account"):
            raise QueryError("unknown name '%s'" % name, pos)
        if i < len(t) and t[i] == '"':
            value, j = self.quoted(i)
            if value == "":
                raise QueryError("empty quotes", pos)
        else:
            value, j = self.bare(i)
            if value == "":
                raise QueryError("missing value for '%s'" % name, pos)
        return _Tok("term", pos, self.make_colon(lname, value, pos)), j

    def make_colon(self, name, value, pos):
        if name == "payee":
            return _Func(lambda tx, p: _contains(tx.payee, value))
        if name == "narration":
            return _Func(lambda tx, p: _contains(tx.narration, value))
        if name == "tag":
            tag = value.lower()
            return _Func(lambda tx, p: tag in (tx.tags or ()))
        if name == "date":
            try:
                period = Period.parse(value)
            except DateError:
                raise QueryError("invalid period '%s'" % value, pos) from None
            return _Func(lambda tx, p: period.start <= tx.date <= period.end)
        if name == "flag":
            if value not in ("*", "!"):
                raise QueryError("invalid flag '%s'" % value, pos)
            return _Func(lambda tx, p: tx.flag == value)
        if name == "id":
            if not re.fullmatch(r"[0-9]+", value):
                raise QueryError("invalid id '%s'" % value, pos)
            n = int(value)
            return _Func(lambda tx, p: tx.id is not None and tx.id == n)
        # account
        parts = value.split(":")
        for part in parts:
            if part not in ("*", "**") and not _PART_RE.fullmatch(part):
                raise QueryError("invalid account pattern '%s'" % value, pos)
        if self.chart is not None:
            if not any(account_pattern_matches(parts, a.path) for a in self.chart.accounts()):
                raise QueryError("no account matches 'account:%s'" % value, pos)
        return _Func(lambda tx, p: p is not None and isinstance(p.account, str)
                     and account_pattern_matches(parts, p.account))

    def cmp_term(self, start, name, i):
        t = self.text
        pos = start + 1
        lname = name.lower()
        op = None
        k = start + len(name)
        while t[k] == " ":
            k += 1
        op = next(o for o in _OPS if t.startswith(o, k))
        if lname not in ("date", "amount"):
            raise QueryError("unknown name '%s'" % name, pos)
        while i < len(t) and t[i] == " ":
            i += 1
        value, j = self.bare(i)
        if value == "":
            raise QueryError("missing value for '%s'" % name, pos)
        if lname == "date":
            try:
                day = parse_date(value)
            except DateError:
                raise QueryError("invalid date '%s'" % value, pos) from None
            return _Tok("term", pos, _Func(lambda tx, p: _compare(tx.date, op, day))), j
        m = _NUM_RE.fullmatch(value)
        if not m or (m.group(2) and (not re.fullmatch(r"[A-Z]{3}", m.group(2)) or m.group(2) not in CURRENCIES)):
            raise QueryError("invalid amount '%s'" % value, pos)
        number = Fraction(m.group(1))
        cur = m.group(2) or None

        def fn(tx, p):
            if p is None or p.amount is None:
                return False
            if cur is not None and p.amount.currency != cur:
                return False
            v = Fraction(p.amount.minor, 10 ** p.amount.exponent)
            return _compare(v, op, number)

        return _Tok("term", pos, _Func(fn)), j


# -- parser -------------------------------------------------------------------

class _Parser:
    def __init__(self, tokens, end_pos):
        self.toks = tokens
        self.i = 0
        self.end_pos = end_pos

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None

    def where(self):
        tok = self.peek()
        return tok.pos if tok else self.end_pos

    def parse(self):
        node = self.or_expr()
        tok = self.peek()
        if tok is not None:
            raise QueryError("unmatched ')'" if tok.kind == ")" else "unexpected '%s'" % tok.kind, tok.pos)
        return node

    def or_expr(self):
        node = self.and_expr()
        while self.peek() is not None and self.peek().kind == "or":
            self.i += 1
            node = _Or(node, self.and_expr())
        return node

    def and_expr(self):
        node = self.not_expr()
        while True:
            tok = self.peek()
            if tok is None:
                return node
            if tok.kind == "and":
                self.i += 1
                node = _And(node, self.not_expr())
            elif tok.kind in ("term", "not", "("):
                node = _And(node, self.not_expr())
            else:
                return node

    def not_expr(self):
        tok = self.peek()
        if tok is not None and tok.kind == "not":
            self.i += 1
            return _Not(self.not_expr())
        return self.primary()

    def primary(self):
        tok = self.peek()
        if tok is None:
            raise QueryError("a term was expected", self.end_pos)
        if tok.kind == "term":
            self.i += 1
            return tok.node
        if tok.kind == "(":
            self.i += 1
            node = self.or_expr()
            close = self.peek()
            if close is None:
                raise QueryError("unclosed '('", tok.pos)
            if close.kind != ")":
                raise QueryError("expected ')'", close.pos)
            self.i += 1
            return node
        raise QueryError("a term was expected, not '%s'" % tok.kind, tok.pos)


class Query:
    def __init__(self, text, node):
        self.text = text
        self._node = node

    @property
    def is_empty(self):
        return self._node is None

    def __repr__(self):
        return "Query(%r)" % (self.text,)

    def _ok(self, tx, p):
        return self._node.ev(tx, p)

    def matches(self, tx):
        if self._node is None:
            return True
        return any(self._node.ev(tx, p) for p in tx.postings)

    def matching_postings(self, tx):
        if self._node is None:
            return list(tx.postings)
        return [p for p in tx.postings if self._node.ev(tx, p)]


def parse_query(text, chart=None):
    if not isinstance(text, str):
        raise QueryError("query must be text", 1)
    if text.strip(" ") == "":
        return Query(text, None)
    tokens = _Lexer(text, chart).tokens()
    node = _Parser(tokens, len(text) + 1).parse()
    return Query(text, node)


def select(transactions, q):
    if not isinstance(q, Query):
        q = parse_query(q)
    return [tx for tx in transactions if q.matches(tx)]

"""Rules that sort transactions into accounts."""

import re
from dataclasses import replace as _dc_replace
from fractions import Fraction

from tallybook.dates import DateError, parse_date
from tallybook.errors import ParseError
from tallybook.model import Posting, Transaction
from tallybook.money import Money


class RulesError(ParseError):
    def __init__(self, line, description):
        super().__init__("line %d: %s" % (line, description))
        self.line = line


_OPS = ("!~", "!=", "<=", ">=", "<", ">", "=", "~")
_OP_CHARS = "<>=~!"
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")
_ACCOUNT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*(?::[A-Z][A-Za-z0-9_-]*)*")
_AMOUNT_RE = re.compile(r"([+-]?[0-9]+(?:\.[0-9]+)?)([A-Z]{3})?")
_TEXT_FIELDS = ("payee", "narration")


def _compare(a, op, b):
    return {"<": a < b, "<=": a <= b, ">": a > b, ">=": a >= b, "=": a == b, "!=": a != b}[op]


def _tokenize(line, lineno):
    toks = []  # (kind, value): kind in 'word', 'str', 'op'
    i, n = 0, len(line)
    while i < n:
        c = line[i]
        if c in " \t":
            i += 1
            continue
        if c == '"':
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    raise RulesError(lineno, "string is never closed")
                ch = line[j]
                if ch == "\\" and j + 1 < n:
                    if line[j + 1] == '"':
                        buf.append('"')
                    else:
                        buf.append(line[j:j + 2])
                    j += 2
                    continue
                if ch == "\\":
                    raise RulesError(lineno, "string is never closed")
                if ch == '"':
                    j += 1
                    break
                buf.append(ch)
                j += 1
            toks.append(("str", "".join(buf)))
            i = j
            continue
        op = next((o for o in _OPS if line.startswith(o, i)), None)
        if op is not None:
            toks.append(("op", op))
            i += len(op)
            continue
        j = i + 1 if c == "!" else i
        while j < n and line[j] not in ' \t"' and line[j] not in _OP_CHARS:
            j += 1
        toks.append(("word", line[i:j]))
        i = j
    return toks


class _Cond:
    def __init__(self, field, op, value, currency=None):
        self.field, self.op, self.value, self.currency = field, op, value, currency

    def holds(self, fields):
        f = self.field
        if f in _TEXT_FIELDS:
            text = fields.get(f)
            if text is None:
                text = ""
            if not isinstance(text, str):
                text = str(text)
            if self.op == "=":
                return text.lower() == self.value.lower()
            if self.op == "!=":
                return text.lower() != self.value.lower()
            found = self.value.search(text) is not None
            return found if self.op == "~" else not found
        if f == "amount":
            amt = fields.get("amount")
            if not isinstance(amt, Money):
                return False
            if self.currency is not None and amt.currency != self.currency:
                return False
            return _compare(Fraction(amt.minor, 10 ** amt.exponent), self.op, self.value)
        d = fields.get("date")
        if d is None:
            return False
        return _compare(d, self.op, self.value)


class Rule:
    def __init__(self, line, conditions, actions):
        self.line = line
        self.conditions = conditions  # empty list: 'any'
        self.actions = actions

    def __repr__(self):
        return "Rule(line=%d)" % self.line

    def matches(self, fields):
        return all(c.holds(fields) for c in self.conditions)

    def result(self):
        out = {}
        for k, v in self.actions.items():
            out[k] = list(v) if isinstance(v, list) else v
        return out


def _parse_rule(line, lineno):
    toks = _tokenize(line, lineno)
    if not toks or toks[0] != ("word", "when"):
        raise RulesError(lineno, "a rule must start with 'when'")
    i = 1
    conds = []
    any_seen = False

    def need(what):
        if i >= len(toks):
            raise RulesError(lineno, "missing %s" % what)
        return toks[i]

    # conditions
    while True:
        kind, val = need("a condition")
        if kind == "word" and val == "then":
            raise RulesError(lineno, "missing condition before 'then'")
        if kind == "word" and val == "any":
            if any_seen:
                raise RulesError(lineno, "'any' cannot be combined with other conditions")
            any_seen = True
            i += 1
        else:
            if kind != "word":
                raise RulesError(lineno, "expected a field name")
            field = val
            if field not in ("payee", "narration", "amount", "date"):
                raise RulesError(lineno, "unknown field '%s'" % field)
            i += 1
            kind, op = need("an operator")
            if kind != "op":
                raise RulesError(lineno, "expected an operator after '%s'" % field)
            i += 1
            if field in _TEXT_FIELDS:
                if op not in ("=", "!=", "~", "!~"):
                    raise RulesError(lineno, "operator '%s' does not apply to %s" % (op, field))
                kind, v = need("a value")
                if kind != "str":
                    raise RulesError(lineno, "%s needs a quoted text" % field)
                i += 1
                if op in ("~", "!~"):
                    try:
                        v = re.compile(v, re.IGNORECASE)
                    except (re.error, OverflowError, RecursionError) as e:
                        raise RulesError(lineno, "invalid regular expression: %s" % e) from None
                conds.append(_Cond(field, op, v))
            else:
                if op in ("~", "!~"):
                    raise RulesError(lineno, "operator '%s' does not apply to %s" % (op, field))
                kind, v = need("a value")
                if kind != "word":
                    raise RulesError(lineno, "%s needs a value" % field)
                i += 1
                if field == "amount":
                    m = _AMOUNT_RE.fullmatch(v)
                    if not m:
                        raise RulesError(lineno, "invalid amount '%s'" % v)
                    conds.append(_Cond(field, op, Fraction(m.group(1)), m.group(2)))
                else:
                    try:
                        d = parse_date(v)
                    except DateError:
                        raise RulesError(lineno, "invalid date '%s'" % v) from None
                    conds.append(_Cond(field, op, d))
        if i >= len(toks):
            raise RulesError(lineno, "missing 'then'")
        kind, val = toks[i]
        if (kind, val) == ("word", "and"):
            i += 1
            continue
        if (kind, val) == ("word", "then"):
            i += 1
            break
        raise RulesError(lineno, "unexpected '%s'" % val)
    if any_seen and conds:
        raise RulesError(lineno, "'any' cannot be combined with other conditions")
    # actions
    actions = {}
    if i >= len(toks):
        raise RulesError(lineno, "nothing after 'then'")
    while i < len(toks):
        kind, name = toks[i]
        if kind != "word":
            raise RulesError(lineno, "expected an action")
        if name not in ("account", "tag", "narration", "payee", "flag"):
            raise RulesError(lineno, "unknown action '%s'" % name)
        i += 1
        if i >= len(toks):
            raise RulesError(lineno, "action '%s' needs a value" % name)
        kind, v = toks[i]
        i += 1
        if name != "tag" and name in actions:
            raise RulesError(lineno, "'%s' given twice" % name)
        if name == "account":
            if kind != "word" or not _ACCOUNT_RE.fullmatch(v):
                raise RulesError(lineno, "invalid account '%s'" % v)
            actions["account"] = v
        elif name == "tag":
            if kind != "word" or not _TAG_RE.fullmatch(v):
                raise RulesError(lineno, "invalid tag '%s'" % v)
            tags = actions.setdefault("tags", [])
            if v.lower() not in tags:
                tags.append(v.lower())
        elif name == "flag":
            if kind != "word" or v not in ("*", "!"):
                raise RulesError(lineno, "invalid flag '%s'" % v)
            actions["flag"] = v
        else:
            if kind != "str":
                raise RulesError(lineno, "%s needs a quoted text" % name)
            if name == "payee" and not v.strip():
                raise RulesError(lineno, "payee must not be empty")
            actions[name] = v
    return Rule(lineno, conds, actions)


class RuleSet:
    def __init__(self, rules=None):
        self._rules = list(rules or [])

    def __len__(self):
        return len(self._rules)

    def __iter__(self):
        return iter(self._rules)

    def match(self, fields):
        for r in self._rules:
            if r.matches(fields):
                return r
        return None

    def apply(self, fields):
        r = self.match(fields)
        return None if r is None else r.result()

    def categorize(self, tx):
        amount = tx.postings[0].amount if tx.postings else None
        fields = {"payee": tx.payee, "narration": tx.narration, "date": tx.date}
        if amount is not None:
            fields["amount"] = amount
        res = self.apply(fields)
        if res is None:
            return tx
        postings = list(tx.postings)
        if "account" in res and len(postings) == 2:
            p = postings[1]
            postings[1] = Posting(res["account"], p.amount, p.note)
        tags = tuple(sorted(set(tx.tags) | set(res.get("tags", []))))
        return Transaction(tx.date, res.get("payee", tx.payee), res.get("narration", tx.narration), postings,
                           tags, res.get("flag", tx.flag), tx.id)


def parse_rules(text):
    if not isinstance(text, str):
        raise RulesError(1, "rules must be text")
    if text.startswith("﻿"):
        text = text[1:]
    rules = []
    lines = text.split("\n")
    for idx, raw in enumerate(lines):
        line = raw[:-1] if raw.endswith("\r") else raw
        s = line.strip(" \t")
        if not s or s.startswith("#"):
            continue
        rules.append(_parse_rule(line, idx + 1))
    return RuleSet(rules)

"""Importing bank CSV statements through a profile."""

import re
from collections import Counter
from dataclasses import dataclass, field
from datetime import date
from typing import List, Optional, Tuple

from tallybook.currency import CURRENCIES
from tallybook.errors import ParseError
from tallybook.model import Posting, Transaction
from tallybook.money import Money


class CsvImportError(ParseError):
    def __init__(self, message, line=None):
        if line is not None:
            message = "line %d: %s" % (line, message)
        super().__init__(message)
        self.line = line


_SETTINGS = ("date_column", "date_format", "payee_column", "narration_column", "amount_column", "debit_column",
             "credit_column", "currency", "account", "default_account", "delimiter", "skip_rows", "has_header",
             "negate", "decimal_separator", "thousands_separator", "flag", "tags")
_COLUMNS = ("date_column", "payee_column", "narration_column", "amount_column", "debit_column", "credit_column")
_ACCOUNT_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*(?::[A-Z][A-Za-z0-9_-]*)*")
_TAG_RE = re.compile(r"[A-Za-z0-9_-]+")
_DELIM_WORDS = {"comma": ",", "tab": "\t", "semicolon": ";", "pipe": "|", "space": " "}
_THOUSANDS = {"none": "", "comma": ",", "dot": ".", "space": " ", "apostrophe": "'",
              ",": ",", ".": ".", "'": "'", " ": " "}
_BOOL = {"yes": True, "true": True, "no": False, "false": False}
MONTHS = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october",
          "november", "december"]


@dataclass
class ImportProfile:
    date_column: str = ""
    payee_column: str = ""
    currency: str = ""
    account: str = ""
    date_format: str = "%Y-%m-%d"
    narration_column: Optional[str] = None
    amount_column: Optional[str] = None
    debit_column: Optional[str] = None
    credit_column: Optional[str] = None
    default_account: Optional[str] = None
    delimiter: str = ","
    skip_rows: int = 0
    has_header: bool = True
    negate: bool = False
    decimal_separator: str = "."
    thousands_separator: str = ""
    flag: str = "*"
    tags: Tuple[str, ...] = ()


def compile_date_format(fmt):
    """Return (regex, order) for a date format, or raise ValueError."""
    parts = []
    order = []
    i = 0
    while i < len(fmt):
        c = fmt[i]
        if c == "%":
            if i + 1 >= len(fmt):
                raise ValueError("lone %")
            d = fmt[i + 1]
            if d == "Y":
                parts.append("([0-9]{4})")
            elif d == "y":
                parts.append("([0-9]{2})")
            elif d in "md":
                parts.append("([0-9]{1,2})")
            elif d == "b":
                parts.append("([A-Za-z]{3})")
            elif d == "B":
                parts.append("([A-Za-z]+)")
            elif d == "%":
                parts.append("%")
                i += 2
                continue
            else:
                raise ValueError("unknown directive %%%s" % d)
            order.append(d)
            i += 2
            continue
        parts.append(re.escape(c))
        i += 1
    years = sum(order.count(x) for x in "Yy")
    months = sum(order.count(x) for x in "mbB")
    days = order.count("d")
    if years != 1 or months != 1 or days != 1:
        raise ValueError("needs a year, a month and a day, each once")
    return re.compile("".join(parts)), order


def parse_date_with(text, fmt):
    rx, order = compile_date_format(fmt)
    m = rx.fullmatch(text)
    if not m:
        return None
    y = mo = d = None
    for directive, value in zip(order, m.groups()):
        if directive == "Y":
            y = int(value)
        elif directive == "y":
            y = 2000 + int(value)
        elif directive == "m":
            mo = int(value)
        elif directive == "d":
            d = int(value)
        elif directive == "b":
            names = [n[:3] for n in MONTHS]
            if value.lower() not in names:
                return None
            mo = names.index(value.lower()) + 1
        else:
            if value.lower() not in MONTHS:
                return None
            mo = MONTHS.index(value.lower()) + 1
    try:
        return date(y, mo, d)
    except ValueError:
        return None


def _column_ok(value, has_header):
    if value.startswith("#"):
        return re.fullmatch(r"[0-9]+", value[1:]) is not None and int(value[1:]) >= 1
    if not value:
        return False
    return has_header


def parse_profile(text):
    if not isinstance(text, str):
        raise CsvImportError("profile must be text")
    if text.startswith("﻿"):
        text = text[1:]
    entries = []
    seen = set()
    for idx, raw in enumerate(re.split(r"\r\n|\n|\r", text)):
        lineno = idx + 1
        s = raw.strip()
        if not s or s.startswith("#"):
            continue
        if "=" not in s:
            raise CsvImportError("expected 'setting = value'", lineno)
        name, value = s.split("=", 1)
        name = name.strip()
        value = value.strip()
        if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
            value = value[1:-1]
        if name not in _SETTINGS:
            raise CsvImportError("unknown setting '%s'" % name, lineno)
        if name in seen:
            raise CsvImportError("setting '%s' given twice" % name, lineno)
        seen.add(name)
        entries.append((name, value, lineno))
    has_header = True
    for name, value, _ in entries:
        if name == "has_header" and value.lower() in _BOOL:
            has_header = _BOOL[value.lower()]
    p = ImportProfile()
    for name, value, lineno in entries:
        bad = lambda what: CsvImportError("invalid %s '%s'" % (what, value), lineno)
        if name in _COLUMNS:
            if not _column_ok(value, has_header):
                if not value.startswith("#") and value and not has_header:
                    raise CsvImportError("column '%s' must be written #N when has_header = no" % value, lineno)
                raise bad(name)
            setattr(p, name, value)
        elif name in ("account", "default_account"):
            if not _ACCOUNT_RE.fullmatch(value):
                raise bad("account")
            setattr(p, name, value)
        elif name == "currency":
            if value not in CURRENCIES:
                raise CsvImportError("unknown currency '%s'" % value, lineno)
            p.currency = value
        elif name == "date_format":
            try:
                compile_date_format(value)
            except ValueError as e:
                raise CsvImportError("invalid date_format '%s': %s" % (value, e), lineno) from None
            p.date_format = value
        elif name == "delimiter":
            if value in _DELIM_WORDS:
                p.delimiter = _DELIM_WORDS[value]
            elif len(value) == 1 and value not in '"\r\n':
                p.delimiter = value
            else:
                raise bad("delimiter")
        elif name == "skip_rows":
            if not re.fullmatch(r"[0-9]+", value):
                raise bad("skip_rows")
            p.skip_rows = int(value)
        elif name in ("has_header", "negate"):
            if value.lower() not in _BOOL:
                raise bad(name)
            setattr(p, name, _BOOL[value.lower()])
        elif name == "decimal_separator":
            if value not in (".", ","):
                raise bad(name)
            p.decimal_separator = value
        elif name == "thousands_separator":
            if value not in _THOUSANDS:
                raise bad(name)
            p.thousands_separator = _THOUSANDS[value]
        elif name == "flag":
            if value not in ("*", "!"):
                raise bad("flag")
            p.flag = value
        elif name == "tags":
            items = [t.strip() for t in value.split(",")]
            if not value or any(not _TAG_RE.fullmatch(t) for t in items):
                raise bad("tags")
            p.tags = tuple(sorted(set(t.lower() for t in items)))
    for req in ("date_column", "payee_column", "currency", "account"):
        if req not in seen:
            raise CsvImportError("missing required setting '%s'" % req)
    has_amount = "amount_column" in seen
    has_debit = "debit_column" in seen
    has_credit = "credit_column" in seen
    if has_amount and (has_debit or has_credit):
        raise CsvImportError("amount_column cannot be combined with debit_column/credit_column")
    if not has_amount and has_debit != has_credit:
        raise CsvImportError("debit_column and credit_column must be given together")
    if not has_amount and not has_debit:
        raise CsvImportError("missing amount_column (or debit_column and credit_column)")
    if p.thousands_separator and p.thousands_separator == p.decimal_separator:
        raise CsvImportError("decimal and thousands separators must differ")
    return p


# -- CSV reading ----------------------------------------------------------------

def read_csv_records(text, delimiter, first_line=1):
    """Parse CSV text; return a list of (start_line, fields, quoted_any)."""
    records = []
    i = 0
    n = len(text)
    line = first_line
    while i < n:
        start = line
        fields = []
        buf = []
        quoted_any = False
        in_field_quoted = False
        while True:
            if i >= n:
                fields.append("".join(buf))
                break
            c = text[i]
            if not buf and not in_field_quoted and c == '"' and _field_start(text, i, delimiter):
                quoted_any = True
                in_field_quoted = True
                i += 1
                while i < n:
                    c = text[i]
                    if c == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            buf.append('"')
                            i += 2
                            continue
                        i += 1
                        break
                    if c == "\n":
                        line += 1
                    elif c == "\r" and not (i + 1 < n and text[i + 1] == "\n"):
                        line += 1
                    buf.append(c)
                    i += 1
                continue
            if c == delimiter:
                fields.append("".join(buf))
                buf = []
                in_field_quoted = False
                i += 1
                continue
            if c == "\n" or (c == "\r" and i + 1 < n and text[i + 1] == "\n"):
                i += 2 if c == "\r" else 1
                fields.append("".join(buf))
                line += 1
                break
            buf.append(c)
            i += 1
        records.append((start, fields, quoted_any))
    return records


def _field_start(text, i, delimiter):
    return i == 0 or text[i - 1] in (delimiter, "\n", "\r")


def _skip_lines(text, count):
    pos = 0
    for _ in range(count):
        m = re.compile(r"\r\n|\n|\r").search(text, pos)
        if not m:
            return len(text)
        pos = m.end()
    return pos


# -- amounts --------------------------------------------------------------------

def parse_csv_amount(cell, profile):
    """Return minor units for an amount cell, or None if it is malformed."""
    exp = CURRENCIES[profile.currency].exponent
    text = cell
    negative = False
    if text.startswith("(") and text.endswith(")"):
        text = text[1:-1]
        negative = True
        if text[:1] in ("+", "-"):
            return None
    else:
        if text[:1] in ("+", "-"):
            negative = text[0] == "-"
            text = text[1:]
    t = re.escape(profile.thousands_separator) if profile.thousands_separator else None
    d = re.escape(profile.decimal_separator)
    whole_rx = "[0-9]+" if t is None else "(?:[0-9]{1,3}(?:%s[0-9]{3})+|[0-9]+)" % t
    m = re.fullmatch("(%s)(?:%s([0-9]+))?" % (whole_rx, d), text)
    if not m:
        return None
    whole = m.group(1)
    if t is not None:
        whole = whole.replace(profile.thousands_separator, "")
    frac = m.group(2)
    if frac is not None and (exp == 0 or len(frac) > exp):
        return None
    value = int(whole) * 10 ** exp + (int(frac.ljust(exp, "0")) if frac else 0)
    return -value if negative else value


def _clean(text):
    return " ".join(text.split())


@dataclass
class ImportResult:
    transactions: List[Transaction] = field(default_factory=list)
    duplicates: List[Transaction] = field(default_factory=list)
    errors: List[Tuple[int, str]] = field(default_factory=list)
    rows: List[int] = field(default_factory=list)  # row number of each new transaction
    ordered: list = field(default_factory=list)  # (transaction, is_duplicate) in file order


def import_key(tx, account):
    for p in tx.postings:
        if p.account == account and p.amount is not None:
            return (tx.date, p.amount, tx.payee)
    return None


def import_csv(text, profile, rules=None, existing=()):
    from tallybook.rules import RuleSet, parse_rules

    if not isinstance(profile, ImportProfile):
        profile = parse_profile(profile)
    if rules is not None and not isinstance(rules, RuleSet):
        rules = parse_rules(rules)
    if not isinstance(text, str):
        raise CsvImportError("statement must be text")
    if text.startswith("﻿"):
        text = text[1:]
    pos = _skip_lines(text, profile.skip_rows)
    first_line = 1 + profile.skip_rows
    records = read_csv_records(text[pos:], profile.delimiter, first_line)
    records = [r for r in records if any(c.strip() for c in r[1])]

    columns = {}
    if profile.has_header:
        if not records:
            raise CsvImportError("the statement has no header")
        header = [h.strip().lower() for h in records[0][1]]
        records = records[1:]
    else:
        header = None
    for name in _COLUMNS:
        value = getattr(profile, name)
        if value is None:
            continue
        if value.startswith("#"):
            columns[name] = int(value[1:]) - 1
        else:
            key = value.strip().lower()
            if key not in header:
                raise CsvImportError("column '%s' is not in the header" % value)
            columns[name] = header.index(key)

    result = ImportResult()
    rows = []  # (lineno, tx)
    for lineno, cells, _q in records:
        def cell(name):
            idx = columns[name]
            if idx >= len(cells):
                raise _RowError("row has no column '%s'" % getattr(profile, name))
            return cells[idx]

        try:
            raw_date = cell("date_column").strip()
            day = parse_date_with(raw_date, profile.date_format)
            if day is None:
                raise _RowError("invalid date '%s'" % raw_date)
            payee = _clean(cell("payee_column"))
            if not payee:
                raise _RowError("empty payee")
            narration = ""
            if "narration_column" in columns and columns["narration_column"] < len(cells):
                narration = _clean(cells[columns["narration_column"]])
            if "amount_column" in columns:
                raw = cell("amount_column").strip()
                if not raw:
                    raise _RowError("empty amount")
                minor = parse_csv_amount(raw, profile)
                if minor is None:
                    raise _RowError("invalid amount '%s'" % raw)
            else:
                debit = cell("debit_column").strip()
                credit = cell("credit_column").strip()
                if debit and credit:
                    raise _RowError("both debit and credit are filled")
                if not debit and not credit:
                    raise _RowError("neither debit nor credit is filled")
                raw = debit or credit
                minor = parse_csv_amount(raw, profile)
                if minor is None:
                    raise _RowError("invalid amount '%s'" % raw)
                if debit:
                    minor = -minor
            if profile.negate:
                minor = -minor
            if minor == 0:
                raise _RowError("amount is zero")
            amount = Money(minor, profile.currency)
            flag = profile.flag
            tags = set(profile.tags)
            counter = None
            if rules is not None:
                res = rules.apply({"payee": payee, "narration": narration, "date": day, "amount": amount})
                if res is not None:
                    counter = res.get("account")
                    payee = res.get("payee", payee)
                    narration = res.get("narration", narration)
                    flag = res.get("flag", flag)
                    tags |= set(res.get("tags", []))
            if counter is None:
                counter = profile.default_account
            if counter is None:
                raise _RowError("no rule gives an account and there is no default_account")
            tx = Transaction(day, payee, narration,
                             [Posting(profile.account, amount), Posting(counter, -amount)],
                             tuple(sorted(tags)), flag, None)
            rows.append((lineno, tx))
        except _RowError as e:
            result.errors.append((lineno, str(e)))

    existing_keys = Counter()
    for tx in existing:
        k = import_key(tx, profile.account)
        if k is not None:
            existing_keys[k] += 1
    seen = Counter()
    for lineno, tx in rows:
        k = import_key(tx, profile.account)
        seen[k] += 1
        if existing_keys[k] >= seen[k]:
            result.duplicates.append(tx)
            result.ordered.append((tx, True))
        else:
            result.ordered.append((tx, False))
            result.transactions.append(tx)
            result.rows.append(lineno)
    return result


class _RowError(Exception):
    pass

"""Budgets: allowances per calendar period and how spending compares."""

import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta
from decimal import Decimal
from fractions import Fraction
from typing import Tuple

from tallybook.dates import Period, last_day
from tallybook.errors import ValidationError
from tallybook.money import Money, round_div


class BudgetError(ValidationError):
    """An invalid budget."""


KINDS = ("month", "quarter", "year")
_SEG_RE = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise BudgetError("invalid budget pattern %r" % (pattern,))
    for seg in pattern.split(":"):
        if seg != "*" and not _SEG_RE.fullmatch(seg):
            raise BudgetError("invalid budget pattern %r" % (pattern,))
    return pattern.split(":")


def pattern_matches(pattern, path):
    pat = pattern.split(":")
    segs = path.split(":")
    if len(segs) < len(pat):
        return False
    return all(p == "*" or p == s for p, s in zip(pat, segs))


def percent_text(num, den):
    """num/den*100 rounded to a tenth, halves away from zero, as text."""
    tenths = round_div(abs(num) * 1000, abs(den))
    negative = (num < 0) != (den < 0) and tenths != 0
    return "%s%d.%d" % ("-" if negative else "", tenths // 10, tenths % 10)


@dataclass(frozen=True)
class Budget:
    pattern: str
    period_kind: str
    amount: Money
    start: date

    def __post_init__(self):
        check_pattern(self.pattern)
        if not isinstance(self.period_kind, str) or self.period_kind not in KINDS:
            raise BudgetError("invalid period kind %r: expected month, quarter or year" % (self.period_kind,))
        if not isinstance(self.amount, Money):
            raise BudgetError("budget amount must be Money, got %r" % (self.amount,))
        if self.amount.minor <= 0:
            raise BudgetError("budget amount must be greater than zero")
        if not isinstance(self.start, date) or isinstance(self.start, datetime):
            raise BudgetError("budget start must be a date, got %r" % (self.start,))


def _calendar(d, kind):
    if kind == "month":
        return Period(date(d.year, d.month, 1), date(d.year, d.month, last_day(d.year, d.month)))
    if kind == "quarter":
        m = 3 * ((d.month - 1) // 3) + 1
        return Period(date(d.year, m, 1), date(d.year, m + 2, last_day(d.year, m + 2)))
    return Period(date(d.year, 1, 1), date(d.year, 12, 31))


def first_period(budget):
    return _calendar(budget.start, budget.period_kind)


def allowance(budget, period):
    """The budget's allowance for `period` or None when not in force."""
    first = first_period(budget)
    if first.start > period.end:
        return None
    total = Fraction(0)
    cur = _calendar(max(first.start, period.start), budget.period_kind)
    while cur.start <= period.end:
        lo = max(cur.start, period.start)
        hi = min(cur.end, period.end)
        if hi >= lo:
            total += Fraction((hi - lo).days + 1, cur.days)
        if cur.end >= date(9999, 12, 31):
            break
        cur = _calendar(cur.end + timedelta(days=1), budget.period_kind)
    value = budget.amount.minor * total
    return Money(round_div(value.numerator, value.denominator), budget.amount.currency)


@dataclass(frozen=True)
class BudgetLine:
    pattern: str
    period_kind: str
    budget: Money
    actual: Money
    remaining: Money
    percent: Decimal
    over: bool
    accounts: Tuple[Tuple[str, Money], ...]

    def to_dict(self):
        from tallybook.export import money_to_dict

        return {
            "pattern": self.pattern,
            "period_kind": self.period_kind,
            "budget": money_to_dict(self.budget),
            "actual": money_to_dict(self.actual),
            "remaining": money_to_dict(self.remaining),
            "percent": str(self.percent),
            "over": self.over,
            "accounts": [{"account": a, "amount": money_to_dict(m)} for a, m in self.accounts],
        }


def budget_status(budgets, ledger, period):
    entries = []
    txs = [t for t in ledger.transactions() if period.start <= t.date <= period.end]
    for order, b in enumerate(budgets):
        allow = allowance(b, period)
        if allow is None:
            continue
        cur = b.amount.currency
        per = {}
        for tx in txs:
            for p in tx.postings:
                if p.amount is None or p.amount.currency != cur:
                    continue
                if p.account.split(":")[0] != "Expenses" or not pattern_matches(b.pattern, p.account):
                    continue
                per[p.account] = per.get(p.account, 0) + p.amount.minor
        actual = sum(per.values())
        if allow.minor == 0:
            pct = "0.0" if actual == 0 else "100.0"
        else:
            pct = percent_text(actual, allow.minor)
        line = BudgetLine(
            b.pattern, b.period_kind, allow, Money(actual, cur), Money(allow.minor - actual, cur),
            Decimal(pct), actual > allow.minor,
            tuple((a, Money(v, cur)) for a, v in sorted(per.items()) if v != 0),
        )
        entries.append(((b.pattern, KINDS.index(b.period_kind), b.start, order), line))
    entries.sort(key=lambda e: e[0])
    return [line for _, line in entries]
"""Recurring transactions: schedules, series and their dated copies."""

import re
from dataclasses import dataclass
from datetime import date, datetime, timedelta
from typing import Optional

from tallybook.dates import DateError, add_months, format_date, last_day, parse_date
from tallybook.errors import ValidationError
from tallybook.model import Transaction


class RecurringError(ValidationError):
    """An invalid schedule or recurring item."""


SHAPES = ("daily, weekly on DAY (mon..sun), monthly on N (1-31), monthly on last, yearly on MM-DD, "
          "every N days|weeks|months|years from YYYY-MM-DD")
WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
WEEKDAY_NAMES = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September",
               "October", "November", "December"]
UNITS = {"day": "day", "days": "day", "week": "week", "weeks": "week", "month": "month", "months": "month",
         "year": "year", "years": "year"}
_MAX = date(9999, 12, 31)


def _is_date(v):
    return isinstance(v, date) and not isinstance(v, datetime)


def _bad(text):
    return RecurringError("invalid schedule %r: expected one of: %s" % (text, SHAPES))


@dataclass(frozen=True)
class Schedule:
    kind: str                 # daily, weekly, monthly, yearly, every
    weekday: int = 0          # weekly: 0 = Monday
    day: int = 0              # monthly: 1-31, 0 = last; yearly: day of month
    month: int = 0            # yearly
    n: int = 0                # every
    unit: str = ""            # every: day, week, month, year
    start: Optional[date] = None  # every: the date after 'from'

    def __str__(self):
        if self.kind == "daily":
            return "daily"
        if self.kind == "weekly":
            return "weekly on %s" % WEEKDAYS[self.weekday]
        if self.kind == "monthly":
            return "monthly on %s" % ("last" if self.day == 0 else self.day)
        if self.kind == "yearly":
            return "yearly on %02d-%02d" % (self.month, self.day)
        unit = self.unit if self.n == 1 else self.unit + "s"
        return "every %d %s from %s" % (self.n, unit, format_date(self.start))

    def iter_from(self, d):
        """Yield the schedule's dates on or after d, ascending."""
        try:
            if self.kind == "daily":
                cur = d
                while True:
                    yield cur
                    if cur >= _MAX:
                        return
                    cur += timedelta(days=1)
            elif self.kind == "weekly":
                cur = d + timedelta(days=(self.weekday - d.weekday()) % 7)
                while True:
                    yield cur
                    cur += timedelta(days=7)
            elif self.kind == "monthly":
                y, m = d.year, d.month
                while y <= 9999:
                    ld = last_day(y, m)
                    day = ld if self.day == 0 else min(self.day, ld)
                    cur = date(y, m, day)
                    if cur >= d:
                        yield cur
                    m += 1
                    if m > 12:
                        y, m = y + 1, 1
            elif self.kind == "yearly":
                y = d.year
                while y <= 9999:
                    cur = date(y, self.month, min(self.day, last_day(y, self.month)))
                    if cur >= d:
                        yield cur
                    y += 1
            elif self.unit in ("day", "week"):
                step = self.n * (7 if self.unit == "week" else 1)
                base = self.start
                k = 0
                if d > base:
                    k = -(-(d - base).days // step)
                while True:
                    yield base + timedelta(days=k * step)
                    k += 1
            else:
                months = self.n * (12 if self.unit == "year" else 1)
                base = self.start
                k = 0
                if d > base:
                    diff = (d.year - base.year) * 12 + (d.month - base.month)
                    k = max(0, diff // months - 1)
                while True:
                    cur = add_months(base, k * months)
                    if cur >= d:
                        yield cur
                    k += 1
        except (OverflowError, DateError, ValueError):
            return

    def between(self, start, end):
        out = []
        if end < start:
            return out
        for d in self.iter_from(start):
            if d > end:
                break
            out.append(d)
        return out


def parse_schedule(text):
    if not isinstance(text, str):
        raise _bad(text)
    words = text.lower().split()
    try:
        if words == ["daily"]:
            return Schedule("daily")
        if len(words) == 3 and words[0] == "weekly" and words[1] == "on" and words[2] in WEEKDAYS:
            return Schedule("weekly", weekday=WEEKDAYS.index(words[2]))
        if len(words) == 3 and words[0] == "monthly" and words[1] == "on":
            if words[2] == "last":
                return Schedule("monthly", day=0)
            if re.fullmatch(r"[0-9]{1,2}", words[2]) and 1 <= int(words[2]) <= 31:
                return Schedule("monthly", day=int(words[2]))
        if len(words) == 3 and words[0] == "yearly" and words[1] == "on":
            m = re.fullmatch(r"([0-9]{2})-([0-9]{2})", words[2])
            if m:
                mo, dd = int(m.group(1)), int(m.group(2))
                if 1 <= mo <= 12 and 1 <= dd <= last_day(2024, mo):
                    return Schedule("yearly", day=dd, month=mo)
        if len(words) == 5 and words[0] == "every" and words[3] == "from":
            if re.fullmatch(r"[0-9]+", words[1]) and int(words[1]) >= 1 and words[2] in UNITS:
                start = parse_date(words[4])
                return Schedule("every", n=int(words[1]), unit=UNITS[words[2]], start=start)
    except DateError:
        pass
    raise _bad(text)


def _ordinal(n):
    if 10 <= n % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return "%d%s" % (n, suffix)


def describe(schedule):
    if isinstance(schedule, str):
        schedule = parse_schedule(schedule)
    s = schedule
    if s.kind == "daily":
        return "every day"
    if s.kind == "weekly":
        return "every %s" % WEEKDAY_NAMES[s.weekday]
    if s.kind == "monthly":
        if s.day == 0:
            return "on the last day of every month"
        return "on the %s of every month" % _ordinal(s.day)
    if s.kind == "yearly":
        return "every year on %d %s" % (s.day, MONTH_NAMES[s.month - 1])
    if s.n == 1:
        return "every %s from %s" % (s.unit, format_date(s.start))
    return "every %d %ss from %s" % (s.n, s.unit, format_date(s.start))


_NAME_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


class Recurring:
    def __init__(self, name, schedule, template, start, end=None, count=None):
        if not isinstance(name, str) or not _NAME_RE.fullmatch(name):
            raise RecurringError("invalid recurring name %r" % (name,))
        if isinstance(schedule, str):
            schedule = parse_schedule(schedule)
        elif not isinstance(schedule, Schedule):
            raise RecurringError("invalid schedule %r" % (schedule,))
        if not isinstance(template, Transaction):
            raise RecurringError("the template must be a Transaction")
        if not _is_date(start):
            raise RecurringError("invalid start %r" % (start,))
        if end is not None:
            if not _is_date(end):
                raise RecurringError("invalid end %r" % (end,))
            if end < start:
                raise RecurringError("end %s is before start %s" % (format_date(end), format_date(start)))
        if count is not None and (not isinstance(count, int) or isinstance(count, bool) or count < 1):
            raise RecurringError("invalid count %r: must be a whole number of at least 1" % (count,))
        self.name = name
        self.schedule = schedule
        self.template = template
        self.start = start
        self.end = end
        self.count = count

    def __eq__(self, other):
        if not isinstance(other, Recurring):
            return NotImplemented
        return (self.name, self.schedule, self.template, self.start, self.end, self.count) == \
            (other.name, other.schedule, other.template, other.start, other.end, other.count)

    __hash__ = None

    def __repr__(self):
        return "Recurring(%r, %r, start=%r, end=%r, count=%r)" % (
            self.name, str(self.schedule), self.start, self.end, self.count)


def _series(rec, from_day=None):
    """Yield the series' dates (start, end, count applied) from from_day on."""
    begin = rec.start
    if rec.count is None and from_day is not None and from_day > begin:
        begin = from_day
    n = 0
    for d in rec.schedule.iter_from(begin):
        if rec.end is not None and d > rec.end:
            return
        if rec.count is not None and n >= rec.count:
            return
        n += 1
        yield d


def occurrences(rec, start, end):
    out = []
    if end < start:
        return out
    for d in _series(rec, start):
        if d > end:
            break
        if d >= start:
            out.append(d)
    return out


def next_occurrence(rec, after):
    nxt = None
    try:
        nxt = after + timedelta(days=1)
    except OverflowError:
        return None
    for d in _series(rec, nxt):
        if d > after:
            return d
    return None


def instantiate(rec, on):
    t = rec.template
    tags = tuple(sorted(set(t.tags) | {"recurring"}))
    return Transaction(on, t.payee, t.narration, list(t.postings), tags, t.flag, None)


def expand(recs, start, end):
    items = []
    for pos, rec in enumerate(recs):
        for d in occurrences(rec, start, end):
            items.append((d, rec.name, pos, rec))
    items.sort(key=lambda x: (x[0], x[1], x[2]))
    return [instantiate(rec, d) for d, _n, _p, rec in items]

"""CSV and JSON export, and fixed-width text tables."""

import json
from datetime import date

from tallybook.currency import CurrencyError
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ValidationError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, MoneyError


class ExportError(ValidationError):
    """A table or document that cannot be written or read."""


# -- CSV ----------------------------------------------------------------------

def _csv_field(value):
    text = "" if value is None else str(value)
    if any(c in text for c in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def to_csv(headers, rows):
    lines = [",".join(_csv_field(h) for h in headers)]
    for row in rows:
        lines.append(",".join(_csv_field(c) for c in row))
    return "".join(line + "\n" for line in lines)


CSV_HEADERS = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


def transactions_to_csv(txs):
    rows = []
    for tx in txs:
        head = [tx.id, format_date(tx.date), tx.flag, tx.payee, tx.narration, ";".join(sorted(set(tx.tags)))]
        if not tx.postings:
            rows.append(head + [None, None, None, None])
        for p in tx.postings:
            if p.amount is None:
                rows.append(head + [p.account, None, None, p.note])
            else:
                rows.append(head + [p.account, p.amount.amount_str(), p.amount.currency, p.note])
    return to_csv(CSV_HEADERS, rows)


# -- JSON ---------------------------------------------------------------------

def to_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def money_to_dict(money):
    if money is None:
        return None
    return {"amount": money.amount_str(), "currency": money.currency}


def posting_to_dict(p):
    return {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}


def transaction_to_dict(tx):
    return {
        "id": tx.id,
        "date": format_date(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": sorted(set(tx.tags)),
        "postings": [posting_to_dict(p) for p in tx.postings],
    }


def transactions_to_json(txs):
    return to_json([transaction_to_dict(tx) for tx in txs])


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def money_from_obj(obj, where):
    if not isinstance(obj, dict) or set(obj) != {"amount", "currency"}:
        raise ExportError("%s: amount must be null or an object with amount and currency" % where)
    if not isinstance(obj["amount"], str) or not isinstance(obj["currency"], str):
        raise ExportError("%s: amount and currency must be text" % where)
    try:
        return Money.of(obj["amount"], obj["currency"])
    except (MoneyError, CurrencyError) as e:
        raise ExportError("%s: %s" % (where, e.message)) from None


def transactions_from_json(text):
    try:
        data = json.loads(text)
    except (ValueError, TypeError) as e:
        raise ExportError("not valid JSON: %s" % e) from None
    if not isinstance(data, list):
        raise ExportError("the JSON is not an array")
    out = []
    for n, item in enumerate(data, 1):
        where = "transaction %d" % n
        if not isinstance(item, dict):
            raise ExportError("%s: not an object" % where)
        for k in item:
            if k not in _TX_KEYS:
                raise ExportError("%s: unknown key %r" % (where, k))
        for k in ("date", "payee", "postings"):
            if k not in item:
                raise ExportError("%s: missing %s" % (where, k))
        d = item["date"]
        try:
            day = parse_date(d)
        except DateError:
            raise ExportError("%s: invalid date %r" % (where, d)) from None
        tid = item.get("id")
        if tid is not None and (not isinstance(tid, int) or isinstance(tid, bool) or tid < 1):
            raise ExportError("%s: invalid id %r" % (where, tid))
        flag = item.get("flag", "*")
        if flag not in ("*", "!") or not isinstance(flag, str):
            raise ExportError("%s: invalid flag %r" % (where, flag))
        payee = item["payee"]
        if not isinstance(payee, str):
            raise ExportError("%s: payee must be text" % where)
        narration = item.get("narration", "")
        if not isinstance(narration, str):
            raise ExportError("%s: narration must be text" % where)
        tags = item.get("tags", [])
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            raise ExportError("%s: tags must be a list of text" % where)
        postings_in = item["postings"]
        if not isinstance(postings_in, list):
            raise ExportError("%s: postings must be a list" % where)
        postings = []
        for m, p in enumerate(postings_in, 1):
            pw = "%s posting %d" % (where, m)
            if not isinstance(p, dict):
                raise ExportError("%s: not an object" % pw)
            for k in p:
                if k not in _POSTING_KEYS:
                    raise ExportError("%s: unknown key %r" % (pw, k))
            if "account" not in p or not isinstance(p["account"], str):
                raise ExportError("%s: account missing or not text" % pw)
            note = p.get("note", "")
            if not isinstance(note, str):
                raise ExportError("%s: note must be text" % pw)
            amt = p.get("amount")
            money = None if amt is None else money_from_obj(amt, pw)
            postings.append(Posting(p["account"], money, note))
        out.append(Transaction(day, payee, narration, postings, tuple(sorted(set(tags))), flag, tid))
    return out


# -- tables -------------------------------------------------------------------

def _cell(value):
    text = "" if value is None else str(value)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    headers = [_cell(h) for h in headers]
    if not headers:
        return ""
    n = len(headers)
    if align is None:
        align = ["l"] * n
    else:
        if not isinstance(align, (str, list, tuple)):
            raise ExportError("align must be a string or list of l/r letters")
        align = list(align)
        if len(align) != n or any(a not in ("l", "r") for a in align):
            raise ExportError("align must have one 'l' or 'r' per column")
    table = []
    for row in rows:
        cells = [_cell(c) for c in row]
        if len(cells) != n:
            raise ExportError("a row has %d cells, expected %d" % (len(cells), n))
        table.append(cells)
    widths = [max([len(headers[i])] + [len(r[i]) for r in table]) for i in range(n)]

    def line(cells):
        parts = [c.ljust(w) if a == "l" else c.rjust(w) for c, w, a in zip(cells, widths, align)]
        return "  ".join(parts).rstrip(" ")

    out = [line(headers), line(["-" * w for w in widths])]
    out += [line(r) for r in table]
    return "".join(l + "\n" for l in out)

"""Reports over a ledger, as plain dicts, text and CSV."""

from datetime import date, timedelta

from tallybook.accounts import ROOT_TYPES
from tallybook.budgets import percent_text
from tallybook.currency import currency as _currency
from tallybook.dates import DateError, Period, format_date, periods
from tallybook.errors import ValidationError
from tallybook.export import render_table, to_csv
from tallybook.money import Money, format_minor


class ReportError(ValidationError):
    """A report that cannot be made."""


REPORTS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")


def _m(minor, cur):
    return {"amount": format_minor(minor, cur), "currency": cur}


def _mm(money):
    return _m(money.minor, money.currency)


def _type(path):
    return ROOT_TYPES.get(path.split(":")[0])


def _fd(d):
    return None if d is None else format_date(d)


def _postings(ledger, start=None, end=None):
    for tx in ledger.transactions():
        if start is not None and tx.date < start:
            continue
        if end is not None and tx.date > end:
            continue
        for p in tx.postings:
            if p.amount is not None:
                yield tx, p


def _sums(ledger, start=None, end=None):
    """{(account, currency): minor} of postings in the date range."""
    out = {}
    for _tx, p in _postings(ledger, start, end):
        k = (p.account, p.amount.currency)
        out[k] = out.get(k, 0) + p.amount.minor
    return out


def _add(d, cur, v):
    d[cur] = d.get(cur, 0) + v


def _money_list(d, keep_zero=False):
    return [_m(v, c) for c, v in sorted(d.items()) if keep_zero or v != 0]


# -- trial balance --------------------------------------------------------------

def trial_balance(ledger, as_of=None):
    sums = _sums(ledger, end=as_of)
    accounts = []
    totals = {}
    for (acct, cur), v in sorted(sums.items()):
        if v == 0:
            continue
        t = totals.setdefault(cur, [0, 0])
        if v > 0:
            accounts.append({"account": acct, "type": _type(acct), "debit": _m(v, cur), "credit": None})
            t[0] += v
        else:
            accounts.append({"account": acct, "type": _type(acct), "debit": None, "credit": _m(-v, cur)})
            t[1] += -v
    return {
        "report": "trial_balance",
        "as_of": _fd(as_of),
        "accounts": accounts,
        "totals": [{"currency": c, "debit": _m(d, c), "credit": _m(cr, c), "balanced": d == cr}
                   for c, (d, cr) in sorted(totals.items())],
    }


# -- balance sheet --------------------------------------------------------------

def _convert(ledger, minor, cur, target, on):
    if cur == target:
        return minor
    return ledger.rates.convert(Money(minor, cur), target, on).minor


def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    if convert_to is not None:
        _currency(convert_to)
        if as_of is None:
            raise ReportError("converting a balance sheet needs an as-of date")
    sums = _sums(ledger, end=as_of)
    sections = {"asset": [], "liability": [], "equity": []}
    retained = {}
    for (acct, cur), v in sorted(sums.items()):
        t = _type(acct)
        if t in ("income", "expense"):
            _add(retained, cur, -v)
            continue
        if t not in sections or v == 0:
            continue
        sections[t].append((acct, cur, v if t == "asset" else -v))
    retained = {c: v for c, v in retained.items() if v != 0}
    out = {"report": "balance_sheet", "as_of": _fd(as_of), "currency": convert_to}
    totals = {}
    for key, name in (("asset", "assets"), ("liability", "liabilities"), ("equity", "equity")):
        lines = []
        tot = {}
        for acct, cur, v in sections[key]:
            if convert_to is None:
                lines.append({"account": acct, "balance": _m(v, cur)})
                _add(tot, cur, v)
            else:
                cv = _convert(ledger, v, cur, convert_to, as_of)
                lines.append({"account": acct, "balance": _m(cv, convert_to), "original": _m(v, cur)})
                _add(tot, convert_to, cv)
        sec = {"accounts": lines}
        if key == "equity":
            if convert_to is None:
                sec["retained_earnings"] = _money_list(retained)
                for c, v in retained.items():
                    _add(tot, c, v)
            else:
                if retained:
                    rv = sum(_convert(ledger, v, c, convert_to, as_of) for c, v in sorted(retained.items()))
                    sec["retained_earnings"] = [_m(rv, convert_to)]
                    _add(tot, convert_to, rv)
                else:
                    sec["retained_earnings"] = []
        if convert_to is not None:
            tot.setdefault(convert_to, 0)
        sec["total"] = _money_list(tot, keep_zero=True)
        totals[key] = tot
        out[name] = sec
    curs = set(totals["asset"]) | set(totals["liability"]) | set(totals["equity"])
    out["balanced"] = all(totals["asset"].get(c, 0) == totals["liability"].get(c, 0) + totals["equity"].get(c, 0)
                          for c in curs)
    return out


# -- income statement -----------------------------------------------------------

def income_statement(ledger, period, convert_to=None):
    if convert_to is not None:
        _currency(convert_to)
    sums = _sums(ledger, period.start, period.end)
    out = {"report": "income_statement", "start": _fd(period.start), "end": _fd(period.end),
           "currency": convert_to}
    totals = {}
    for key, name in (("income", "income"), ("expense", "expenses")):
        raw = []
        for (acct, cur), v in sorted(sums.items()):
            if _type(acct) != key or v == 0:
                continue
            raw.append((acct, cur, -v if key == "income" else v))
        tot = {}
        shown = []
        for acct, cur, v in raw:
            if convert_to is None:
                shown.append((acct, cur, v, None))
                _add(tot, cur, v)
            else:
                cv = _convert(ledger, v, cur, convert_to, period.end)
                shown.append((acct, convert_to, cv, (v, cur)))
                _add(tot, convert_to, cv)
        if convert_to is not None:
            tot.setdefault(convert_to, 0)
        lines = []
        for acct, cur, v, orig in shown:
            total = tot.get(cur, 0)
            line = {"account": acct, "amount": _m(v, cur),
                    "percent": "0.0" if total == 0 else percent_text(v, total)}
            if orig is not None:
                line["original"] = _m(orig[0], orig[1])
            lines.append(line)
        totals[key] = tot
        out[name] = {"accounts": lines, "total": _money_list(tot, keep_zero=True)}
    net = {}
    for c in set(totals["income"]) | set(totals["expense"]):
        net[c] = totals["income"].get(c, 0) - totals["expense"].get(c, 0)
    out["net"] = _money_list(net, keep_zero=True)
    return out


# -- cash flow ------------------------------------------------------------------

def _asset_balance(ledger, end, before=False):
    out = {}
    for tx, p in _postings(ledger):
        if (tx.date >= end) if before else (tx.date > end):
            continue
        if _type(p.account) == "asset":
            _add(out, p.amount.currency, p.amount.minor)
    return out


def cashflow(ledger, period):
    contrib = {}
    for tx in ledger.transactions():
        if not (period.start <= tx.date <= period.end):
            continue
        asset_sum = {}
        for p in tx.postings:
            if p.amount is not None and _type(p.account) == "asset":
                _add(asset_sum, p.amount.currency, p.amount.minor)
        for p in tx.postings:
            if p.amount is None or _type(p.account) == "asset":
                continue
            if asset_sum.get(p.amount.currency, 0) == 0:
                continue
            k = (p.account, p.amount.currency)
            contrib[k] = contrib.get(k, 0) - p.amount.minor
    currencies = set()
    for tx, p in _postings(ledger, end=period.end):
        if _type(p.account) == "asset":
            currencies.add(p.amount.currency)
    opening = _asset_balance(ledger, period.start, before=True)
    closing = _asset_balance(ledger, period.end)
    inflows, outflows = [], []
    t_in = {c: 0 for c in currencies}
    t_out = {c: 0 for c in currencies}
    for (acct, cur), v in sorted(contrib.items()):
        if v > 0:
            inflows.append({"account": acct, "amount": _m(v, cur)})
            _add(t_in, cur, v)
        elif v < 0:
            outflows.append({"account": acct, "amount": _m(-v, cur)})
            _add(t_out, cur, -v)
    cs = sorted(currencies | set(t_in) | set(t_out))
    return {
        "report": "cashflow", "start": _fd(period.start), "end": _fd(period.end),
        "opening": [_m(opening.get(c, 0), c) for c in cs],
        "inflows": inflows, "outflows": outflows,
        "total_in": [_m(t_in.get(c, 0), c) for c in cs],
        "total_out": [_m(t_out.get(c, 0), c) for c in cs],
        "net": [_m(t_in.get(c, 0) - t_out.get(c, 0), c) for c in cs],
        "closing": [_m(closing.get(c, 0), c) for c in cs],
    }


# -- register -------------------------------------------------------------------

def register(ledger, account, period=None, rollup=False):
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account: %s" % (account,))

    def selected(path):
        return path == account or (rollup and path.startswith(account + ":"))

    start = period.start if period is not None else None
    end = period.end if period is not None else None
    opening = {}
    currencies = set()
    rows = []
    running = None
    items = []
    for tx in ledger.transactions():
        for p in tx.postings:
            if p.amount is None or not selected(p.account):
                continue
            if end is not None and tx.date > end:
                continue
            currencies.add(p.amount.currency)
            if start is not None and tx.date < start:
                _add(opening, p.amount.currency, p.amount.minor)
            else:
                items.append((tx, p))
    running = dict(opening)
    for tx, p in items:
        cur = p.amount.currency
        _add(running, cur, p.amount.minor)
        rows.append({"date": _fd(tx.date), "id": tx.id, "payee": tx.payee, "narration": tx.narration,
                     "account": p.account, "amount": _m(p.amount.minor, cur), "balance": _m(running[cur], cur)})
    cs = sorted(currencies)
    return {
        "report": "register", "account": account, "rollup": bool(rollup),
        "start": _fd(start), "end": _fd(end),
        "opening": [_m(opening.get(c, 0), c) for c in cs],
        "rows": rows,
        "closing": [_m(running.get(c, 0), c) for c in cs],
    }


# -- net worth ------------------------------------------------------------------

def net_worth(ledger, period, step="month"):
    if not isinstance(step, str) or step not in ("week", "month", "quarter", "year"):
        raise ReportError("invalid step %r: expected week, month, quarter or year" % (step,))
    try:
        steps = periods(period.start, period.end, step)
    except DateError as e:
        raise ReportError(e.message) from None
    points = []
    all_postings = list(_postings(ledger))
    for p in steps:
        d = p.end
        assets, liabs = {}, {}
        for tx, ps in all_postings:
            if tx.date > d:
                continue
            t = _type(ps.account)
            if t == "asset":
                _add(assets, ps.amount.currency, ps.amount.minor)
                liabs.setdefault(ps.amount.currency, 0)
            elif t == "liability":
                _add(liabs, ps.amount.currency, -ps.amount.minor)
                assets.setdefault(ps.amount.currency, 0)
        cs = sorted(assets)
        points.append({"date": _fd(d),
                       "assets": [_m(assets[c], c) for c in cs],
                       "liabilities": [_m(liabs[c], c) for c in cs],
                       "net": [_m(assets[c] - liabs[c], c) for c in cs]})
    return {"report": "net_worth", "start": _fd(period.start), "end": _fd(period.end), "step": step,
            "points": points}


# -- text -----------------------------------------------------------------------

def _check(report):
    if not isinstance(report, dict) or report.get("report") not in REPORTS:
        raise ReportError("not a report")
    return report["report"]


def _t(money):
    if money is None:
        return ""
    return "%s %s" % (money["amount"], money["currency"])


def _blocks(blocks, width):
    rows = []
    for b in blocks:
        if not b:
            continue
        if rows:
            rows.append([""] * width)
        rows.extend(b)
    return rows


def render_text(report):
    kind = _check(report)
    try:
        return _render(kind, report)
    except ReportError:
        raise
    except (KeyError, TypeError, IndexError, AttributeError, ValueError) as e:
        raise ReportError("malformed report: %s" % e) from None


def _conv_suffix(report):
    return " (in %s)" % report["currency"] if report.get("currency") else ""


def _render(kind, r):
    if kind == "trial_balance":
        title = "Trial balance as of %s" % r["as_of"] if r["as_of"] else "Trial balance"
        rows = [[a["account"], a["type"] or "", _t(a["debit"]), _t(a["credit"])] for a in r["accounts"]]
        rows += [["Total", "", _t(t["debit"]), _t(t["credit"])] for t in r["totals"]]
        table = render_table(["Account", "Type", "Debit", "Credit"], rows, "llrr")
    elif kind == "balance_sheet":
        title = ("Balance sheet as of %s" % r["as_of"] if r["as_of"] else "Balance sheet") + _conv_suffix(r)
        blocks = []
        for key, head in (("assets", "Assets"), ("liabilities", "Liabilities"), ("equity", "Equity")):
            sec = r[key]
            b = [[head, ""]]
            b += [["  " + a["account"], _t(a["balance"])] for a in sec["accounts"]]
            if key == "equity":
                b += [["  Retained earnings", _t(m)] for m in sec.get("retained_earnings", [])]
            b += [["Total " + key, _t(m)] for m in sec["total"]]
            blocks.append(b)
        table = render_table(["Account", "Balance"], _blocks(blocks, 2), "lr")
    elif kind == "income_statement":
        title = "Income statement %s to %s" % (r["start"], r["end"]) + _conv_suffix(r)
        blocks = []
        for key, head in (("income", "Income"), ("expenses", "Expenses")):
            sec = r[key]
            b = [[head, "", ""]]
            b += [["  " + a["account"], _t(a["amount"]), a["percent"] + "%"] for a in sec["accounts"]]
            b += [["Total " + key, _t(m), ""] for m in sec["total"]]
            blocks.append(b)
        blocks.append([["Net income", _t(m), ""] for m in r["net"]])
        table = render_table(["Account", "Amount", "Percent"], _blocks(blocks, 3), "lrr")
    elif kind == "cashflow":
        title = "Cash flow %s to %s" % (r["start"], r["end"])
        blocks = [[["Opening balance", _t(m)] for m in r["opening"]]]
        b = [["Money in", ""]] + [["  " + a["account"], _t(a["amount"])] for a in r["inflows"]]
        b += [["Total money in", _t(m)] for m in r["total_in"]]
        blocks.append(b)
        b = [["Money out", ""]] + [["  " + a["account"], _t(a["amount"])] for a in r["outflows"]]
        b += [["Total money out", _t(m)] for m in r["total_out"]]
        blocks.append(b)
        blocks.append([["Net change", _t(m)] for m in r["net"]] + [["Closing balance", _t(m)] for m in r["closing"]])
        table = render_table(["Account", "Amount"], _blocks(blocks, 2), "lr")
    elif kind == "net_worth":
        title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
        rows = []
        for p in r["points"]:
            if not p["assets"]:
                rows.append([p["date"], "", "", ""])
            for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
                rows.append([p["date"], _t(a), _t(l), _t(n)])
        table = render_table(["Date", "Assets", "Liabilities", "Net"], rows, "lrrr")
    else:
        title = "Register %s" % r["account"]
        if r.get("rollup"):
            title += " (with sub-accounts)"
        if r.get("start"):
            title += " %s to %s" % (r["start"], r["end"])
        rows = [["", "", "Opening balance", "", "", _t(m)] for m in r["opening"]]
        rows += [[x["date"], "" if x["id"] is None else x["id"], x["payee"], x["account"], _t(x["amount"]),
                  _t(x["balance"])] for x in r["rows"]]
        rows += [["", "", "Closing balance", "", "", _t(m)] for m in r["closing"]]
        table = render_table(["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr")
    return title + "\n\n" + table


# -- CSV ------------------------------------------------------------------------

def _a(money):
    return (None, None) if money is None else (money["currency"], money["amount"])


def report_to_csv(report):
    kind = _check(report)
    try:
        return _csv(kind, report)
    except ReportError:
        raise
    except (KeyError, TypeError, IndexError, AttributeError, ValueError) as e:
        raise ReportError("malformed report: %s" % e) from None


def _csv(kind, r):
    if kind == "trial_balance":
        rows = []
        for a in r["accounts"]:
            m = a["debit"] or a["credit"]
            rows.append([a["account"], a["type"], m["currency"],
                         a["debit"]["amount"] if a["debit"] else None,
                         a["credit"]["amount"] if a["credit"] else None])
        return to_csv(["account", "type", "currency", "debit", "credit"], rows)
    if kind == "balance_sheet":
        rows = []
        for key in ("assets", "liabilities", "equity"):
            for a in r[key]["accounts"]:
                rows.append([key, a["account"], a["balance"]["currency"], a["balance"]["amount"]])
        for m in r["equity"].get("retained_earnings", []):
            rows.append(["equity", "Retained earnings", m["currency"], m["amount"]])
        return to_csv(["section", "account", "currency", "balance"], rows)
    if kind == "income_statement":
        rows = []
        for key in ("income", "expenses"):
            for a in r[key]["accounts"]:
                rows.append([key, a["account"], a["amount"]["currency"], a["amount"]["amount"], a["percent"]])
        return to_csv(["section", "account", "currency", "amount", "percent"], rows)
    if kind == "cashflow":
        rows = [["opening", "", m["currency"], m["amount"]] for m in r["opening"]]
        rows += [["in", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["inflows"]]
        rows += [["out", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["outflows"]]
        rows += [["closing", "", m["currency"], m["amount"]] for m in r["closing"]]
        return to_csv(["section", "account", "currency", "amount"], rows)
    if kind == "register":
        rows = [[x["date"], x["id"], x["payee"], x["narration"], x["account"], x["amount"]["currency"],
                 x["amount"]["amount"], x["balance"]["amount"]] for x in r["rows"]]
        return to_csv(["date", "id", "payee", "narration", "account", "currency", "amount", "balance"], rows)
    rows = []
    for p in r["points"]:
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], a["currency"], a["amount"], l["amount"], n["amount"]])
    return to_csv(["date", "currency", "assets", "liabilities", "net"], rows)

"""CSV and JSON export, and fixed-width text tables."""

import json
from datetime import date

from tallybook.currency import CurrencyError
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ValidationError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, MoneyError


class ExportError(ValidationError):
    """A table or document that cannot be written or read."""


# -- CSV ----------------------------------------------------------------------

def _csv_field(value):
    text = "" if value is None else str(value)
    if any(c in text for c in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def to_csv(headers, rows):
    lines = [",".join(_csv_field(h) for h in headers)]
    for row in rows:
        lines.append(",".join(_csv_field(c) for c in row))
    return "".join(line + "\n" for line in lines)


CSV_HEADERS = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


def transactions_to_csv(txs):
    rows = []
    for tx in txs:
        head = [tx.id, format_date(tx.date), tx.flag, tx.payee, tx.narration, ";".join(sorted(set(tx.tags)))]
        if not tx.postings:
            rows.append(head + [None, None, None, None])
        for p in tx.postings:
            if p.amount is None:
                rows.append(head + [p.account, None, None, p.note])
            else:
                rows.append(head + [p.account, p.amount.amount_str(), p.amount.currency, p.note])
    return to_csv(CSV_HEADERS, rows)


# -- JSON ---------------------------------------------------------------------

def to_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def money_to_dict(money):
    if money is None:
        return None
    return {"amount": money.amount_str(), "currency": money.currency}


def posting_to_dict(p):
    return {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}


def transaction_to_dict(tx):
    return {
        "id": tx.id,
        "date": format_date(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": sorted(set(tx.tags)),
        "postings": [posting_to_dict(p) for p in tx.postings],
    }


def transactions_to_json(txs):
    return to_json([transaction_to_dict(tx) for tx in txs])


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def money_from_obj(obj, where):
    if not isinstance(obj, dict) or set(obj) != {"amount", "currency"}:
        raise ExportError("%s: amount must be null or an object with amount and currency" % where)
    if not isinstance(obj["amount"], str) or not isinstance(obj["currency"], str):
        raise ExportError("%s: amount and currency must be text" % where)
    try:
        return Money.of(obj["amount"], obj["currency"])
    except (MoneyError, CurrencyError) as e:
        raise ExportError("%s: %s" % (where, e.message)) from None


def transactions_from_json(text):
    try:
        data = json.loads(text)
    except (ValueError, TypeError) as e:
        raise ExportError("not valid JSON: %s" % e) from None
    if not isinstance(data, list):
        raise ExportError("the JSON is not an array")
    out = []
    for n, item in enumerate(data, 1):
        where = "transaction %d" % n
        if not isinstance(item, dict):
            raise ExportError("%s: not an object" % where)
        for k in item:
            if k not in _TX_KEYS:
                raise ExportError("%s: unknown key %r" % (where, k))
        for k in ("date", "payee", "postings"):
            if k not in item:
                raise ExportError("%s: missing %s" % (where, k))
        d = item["date"]
        try:
            day = parse_date(d)
        except DateError:
            raise ExportError("%s: invalid date %r" % (where, d)) from None
        tid = item.get("id")
        if tid is not None and (not isinstance(tid, int) or isinstance(tid, bool) or tid < 1):
            raise ExportError("%s: invalid id %r" % (where, tid))
        flag = item.get("flag", "*")
        if flag not in ("*", "!") or not isinstance(flag, str):
            raise ExportError("%s: invalid flag %r" % (where, flag))
        payee = item["payee"]
        if not isinstance(payee, str):
            raise ExportError("%s: payee must be text" % where)
        narration = item.get("narration", "")
        if not isinstance(narration, str):
            raise ExportError("%s: narration must be text" % where)
        tags = item.get("tags", [])
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            raise ExportError("%s: tags must be a list of text" % where)
        postings_in = item["postings"]
        if not isinstance(postings_in, list):
            raise ExportError("%s: postings must be a list" % where)
        postings = []
        for m, p in enumerate(postings_in, 1):
            pw = "%s posting %d" % (where, m)
            if not isinstance(p, dict):
                raise ExportError("%s: not an object" % pw)
            for k in p:
                if k not in _POSTING_KEYS:
                    raise ExportError("%s: unknown key %r" % (pw, k))
            if "account" not in p or not isinstance(p["account"], str):
                raise ExportError("%s: account missing or not text" % pw)
            note = p.get("note", "")
            if not isinstance(note, str):
                raise ExportError("%s: note must be text" % pw)
            amt = p.get("amount")
            money = None if amt is None else money_from_obj(amt, pw)
            postings.append(Posting(p["account"], money, note))
        out.append(Transaction(day, payee, narration, postings, tuple(sorted(set(tags))), flag, tid))
    return out


# -- tables -------------------------------------------------------------------

def _cell(value):
    text = "" if value is None else str(value)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    headers = [_cell(h) for h in headers]
    if not headers:
        return ""
    n = len(headers)
    if align is None:
        align = ["l"] * n
    else:
        if not isinstance(align, (str, list, tuple)):
            raise ExportError("align must be a string or list of l/r letters")
        align = list(align)
        if len(align) != n or any(a not in ("l", "r") for a in align):
            raise ExportError("align must have one 'l' or 'r' per column")
    table = []
    for row in rows:
        cells = [_cell(c) for c in row]
        if len(cells) != n:
            raise ExportError("a row has %d cells, expected %d" % (len(cells), n))
        table.append(cells)
    widths = [max([len(headers[i])] + [len(r[i]) for r in table]) for i in range(n)]

    def line(cells):
        parts = [c.ljust(w) if a == "l" else c.rjust(w) for c, w, a in zip(cells, widths, align)]
        return "  ".join(parts).rstrip(" ")

    out = [line(headers), line(["-" * w for w in widths])]
    out += [line(r) for r in table]
    return "".join(l + "\n" for l in out)

"""Reports over a ledger, as plain dicts, text and CSV."""

from datetime import date, timedelta

from tallybook.accounts import ROOT_TYPES
from tallybook.budgets import percent_text
from tallybook.currency import currency as _currency
from tallybook.dates import DateError, Period, format_date, periods
from tallybook.errors import ValidationError
from tallybook.export import render_table, to_csv
from tallybook.money import Money, format_minor


class ReportError(ValidationError):
    """A report that cannot be made."""


REPORTS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")


def _m(minor, cur):
    return {"amount": format_minor(minor, cur), "currency": cur}


def _mm(money):
    return _m(money.minor, money.currency)


def _type(path):
    return ROOT_TYPES.get(path.split(":")[0])


def _fd(d):
    return None if d is None else format_date(d)


def _postings(ledger, start=None, end=None):
    for tx in ledger.transactions():
        if start is not None and tx.date < start:
            continue
        if end is not None and tx.date > end:
            continue
        for p in tx.postings:
            if p.amount is not None:
                yield tx, p


def _sums(ledger, start=None, end=None):
    """{(account, currency): minor} of postings in the date range."""
    out = {}
    for _tx, p in _postings(ledger, start, end):
        k = (p.account, p.amount.currency)
        out[k] = out.get(k, 0) + p.amount.minor
    return out


def _add(d, cur, v):
    d[cur] = d.get(cur, 0) + v


def _money_list(d, keep_zero=False):
    return [_m(v, c) for c, v in sorted(d.items()) if keep_zero or v != 0]


# -- trial balance --------------------------------------------------------------

def trial_balance(ledger, as_of=None):
    sums = _sums(ledger, end=as_of)
    accounts = []
    totals = {}
    for (acct, cur), v in sorted(sums.items()):
        if v == 0:
            continue
        t = totals.setdefault(cur, [0, 0])
        if v > 0:
            accounts.append({"account": acct, "type": _type(acct), "debit": _m(v, cur), "credit": None})
            t[0] += v
        else:
            accounts.append({"account": acct, "type": _type(acct), "debit": None, "credit": _m(-v, cur)})
            t[1] += -v
    return {
        "report": "trial_balance",
        "as_of": _fd(as_of),
        "accounts": accounts,
        "totals": [{"currency": c, "debit": _m(d, c), "credit": _m(cr, c), "balanced": d == cr}
                   for c, (d, cr) in sorted(totals.items())],
    }


# -- balance sheet --------------------------------------------------------------

def _convert(ledger, minor, cur, target, on):
    if cur == target:
        return minor
    return ledger.rates.convert(Money(minor, cur), target, on).minor


def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    if convert_to is not None:
        _currency(convert_to)
        if as_of is None:
            raise ReportError("converting a balance sheet needs an as-of date")
    sums = _sums(ledger, end=as_of)
    sections = {"asset": [], "liability": [], "equity": []}
    retained = {}
    for (acct, cur), v in sorted(sums.items()):
        t = _type(acct)
        if t in ("income", "expense"):
            _add(retained, cur, -v)
            continue
        if t not in sections or v == 0:
            continue
        sections[t].append((acct, cur, v if t == "asset" else -v))
    retained = {c: v for c, v in retained.items() if v != 0}
    out = {"report": "balance_sheet", "as_of": _fd(as_of), "currency": convert_to}
    totals = {}
    for key, name in (("asset", "assets"), ("liability", "liabilities"), ("equity", "equity")):
        lines = []
        tot = {}
        for acct, cur, v in sections[key]:
            if convert_to is None:
                lines.append({"account": acct, "balance": _m(v, cur)})
                _add(tot, cur, v)
            else:
                cv = _convert(ledger, v, cur, convert_to, as_of)
                lines.append({"account": acct, "balance": _m(cv, convert_to), "original": _m(v, cur)})
                _add(tot, convert_to, cv)
        sec = {"accounts": lines}
        if key == "equity":
            if convert_to is None:
                sec["retained_earnings"] = _money_list(retained)
                for c, v in retained.items():
                    _add(tot, c, v)
            else:
                if retained:
                    rv = sum(_convert(ledger, v, c, convert_to, as_of) for c, v in sorted(retained.items()))
                    sec["retained_earnings"] = [_m(rv, convert_to)]
                    _add(tot, convert_to, rv)
                else:
                    sec["retained_earnings"] = []
        if convert_to is not None:
            tot.setdefault(convert_to, 0)
        sec["total"] = _money_list(tot, keep_zero=True)
        totals[key] = tot
        out[name] = sec
    curs = set(totals["asset"]) | set(totals["liability"]) | set(totals["equity"])
    out["balanced"] = all(totals["asset"].get(c, 0) == totals["liability"].get(c, 0) + totals["equity"].get(c, 0)
                          for c in curs)
    return out


# -- income statement -----------------------------------------------------------

def income_statement(ledger, period, convert_to=None):
    if convert_to is not None:
        _currency(convert_to)
    sums = _sums(ledger, period.start, period.end)
    out = {"report": "income_statement", "start": _fd(period.start), "end": _fd(period.end),
           "currency": convert_to}
    totals = {}
    for key, name in (("income", "income"), ("expense", "expenses")):
        raw = []
        for (acct, cur), v in sorted(sums.items()):
            if _type(acct) != key or v == 0:
                continue
            raw.append((acct, cur, -v if key == "income" else v))
        tot = {}
        shown = []
        for acct, cur, v in raw:
            if convert_to is None:
                shown.append((acct, cur, v, None))
                _add(tot, cur, v)
            else:
                cv = _convert(ledger, v, cur, convert_to, period.end)
                shown.append((acct, convert_to, cv, (v, cur)))
                _add(tot, convert_to, cv)
        if convert_to is not None:
            tot.setdefault(convert_to, 0)
        lines = []
        for acct, cur, v, orig in shown:
            total = tot.get(cur, 0)
            line = {"account": acct, "amount": _m(v, cur),
                    "percent": "0.0" if total == 0 else percent_text(v, total)}
            if orig is not None:
                line["original"] = _m(orig[0], orig[1])
            lines.append(line)
        totals[key] = tot
        out[name] = {"accounts": lines, "total": _money_list(tot, keep_zero=True)}
    net = {}
    for c in set(totals["income"]) | set(totals["expense"]):
        net[c] = totals["income"].get(c, 0) - totals["expense"].get(c, 0)
    out["net"] = _money_list(net, keep_zero=True)
    return out


# -- cash flow ------------------------------------------------------------------

def _asset_balance(ledger, end, before=False):
    out = {}
    for tx, p in _postings(ledger):
        if (tx.date >= end) if before else (tx.date > end):
            continue
        if _type(p.account) == "asset":
            _add(out, p.amount.currency, p.amount.minor)
    return out


def cashflow(ledger, period):
    contrib = {}
    for tx in ledger.transactions():
        if not (period.start <= tx.date <= period.end):
            continue
        asset_sum = {}
        for p in tx.postings:
            if p.amount is not None and _type(p.account) == "asset":
                _add(asset_sum, p.amount.currency, p.amount.minor)
        for p in tx.postings:
            if p.amount is None or _type(p.account) == "asset":
                continue
            if asset_sum.get(p.amount.currency, 0) == 0:
                continue
            k = (p.account, p.amount.currency)
            contrib[k] = contrib.get(k, 0) - p.amount.minor
    currencies = set()
    for tx, p in _postings(ledger, end=period.end):
        if _type(p.account) == "asset":
            currencies.add(p.amount.currency)
    opening = _asset_balance(ledger, period.start, before=True)
    closing = _asset_balance(ledger, period.end)
    inflows, outflows = [], []
    t_in = {c: 0 for c in currencies}
    t_out = {c: 0 for c in currencies}
    for (acct, cur), v in sorted(contrib.items()):
        if v > 0:
            inflows.append({"account": acct, "amount": _m(v, cur)})
            _add(t_in, cur, v)
        elif v < 0:
            outflows.append({"account": acct, "amount": _m(-v, cur)})
            _add(t_out, cur, -v)
    cs = sorted(currencies | set(t_in) | set(t_out))
    return {
        "report": "cashflow", "start": _fd(period.start), "end": _fd(period.end),
        "opening": [_m(opening.get(c, 0), c) for c in cs],
        "inflows": inflows, "outflows": outflows,
        "total_in": [_m(t_in.get(c, 0), c) for c in cs],
        "total_out": [_m(t_out.get(c, 0), c) for c in cs],
        "net": [_m(t_in.get(c, 0) - t_out.get(c, 0), c) for c in cs],
        "closing": [_m(closing.get(c, 0), c) for c in cs],
    }


# -- register -------------------------------------------------------------------

def register(ledger, account, period=None, rollup=False):
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account: %s" % (account,))

    def selected(path):
        return path == account or (rollup and path.startswith(account + ":"))

    start = period.start if period is not None else None
    end = period.end if period is not None else None
    opening = {}
    currencies = set()
    rows = []
    running = None
    items = []
    for tx in ledger.transactions():
        for p in tx.postings:
            if p.amount is None or not selected(p.account):
                continue
            if end is not None and tx.date > end:
                continue
            currencies.add(p.amount.currency)
            if start is not None and tx.date < start:
                _add(opening, p.amount.currency, p.amount.minor)
            else:
                items.append((tx, p))
    running = dict(opening)
    for tx, p in items:
        cur = p.amount.currency
        _add(running, cur, p.amount.minor)
        rows.append({"date": _fd(tx.date), "id": tx.id, "payee": tx.payee, "narration": tx.narration,
                     "account": p.account, "amount": _m(p.amount.minor, cur), "balance": _m(running[cur], cur)})
    cs = sorted(currencies)
    return {
        "report": "register", "account": account, "rollup": bool(rollup),
        "start": _fd(start), "end": _fd(end),
        "opening": [_m(opening.get(c, 0), c) for c in cs],
        "rows": rows,
        "closing": [_m(running.get(c, 0), c) for c in cs],
    }


# -- net worth ------------------------------------------------------------------

def net_worth(ledger, period, step="month"):
    if not isinstance(step, str) or step not in ("week", "month", "quarter", "year"):
        raise ReportError("invalid step %r: expected week, month, quarter or year" % (step,))
    try:
        steps = periods(period.start, period.end, step)
    except DateError as e:
        raise ReportError(e.message) from None
    points = []
    all_postings = list(_postings(ledger))
    for p in steps:
        d = p.end
        assets, liabs = {}, {}
        for tx, ps in all_postings:
            if tx.date > d:
                continue
            t = _type(ps.account)
            if t == "asset":
                _add(assets, ps.amount.currency, ps.amount.minor)
                liabs.setdefault(ps.amount.currency, 0)
            elif t == "liability":
                _add(liabs, ps.amount.currency, -ps.amount.minor)
                assets.setdefault(ps.amount.currency, 0)
        cs = sorted(assets)
        points.append({"date": _fd(d),
                       "assets": [_m(assets[c], c) for c in cs],
                       "liabilities": [_m(liabs[c], c) for c in cs],
                       "net": [_m(assets[c] - liabs[c], c) for c in cs]})
    return {"report": "net_worth", "start": _fd(period.start), "end": _fd(period.end), "step": step,
            "points": points}


# -- text -----------------------------------------------------------------------

def _check(report):
    if not isinstance(report, dict) or report.get("report") not in REPORTS:
        raise ReportError("not a report")
    return report["report"]


def _t(money):
    if money is None:
        return ""
    return "%s %s" % (money["amount"], money["currency"])


def _blocks(blocks, width):
    rows = []
    for b in blocks:
        if not b:
            continue
        if rows:
            rows.append([""] * width)
        rows.extend(b)
    return rows


def render_text(report):
    kind = _check(report)
    try:
        return _render(kind, report)
    except ReportError:
        raise
    except (KeyError, TypeError, IndexError, AttributeError, ValueError) as e:
        raise ReportError("malformed report: %s" % e) from None


def _conv_suffix(report):
    return " (in %s)" % report["currency"] if report.get("currency") else ""


def _render(kind, r):
    if kind == "trial_balance":
        title = "Trial balance as of %s" % r["as_of"] if r["as_of"] else "Trial balance"
        rows = [[a["account"], a["type"] or "", _t(a["debit"]), _t(a["credit"])] for a in r["accounts"]]
        rows += [["Total", "", _t(t["debit"]), _t(t["credit"])] for t in r["totals"]]
        table = render_table(["Account", "Type", "Debit", "Credit"], rows, "llrr")
    elif kind == "balance_sheet":
        title = ("Balance sheet as of %s" % r["as_of"] if r["as_of"] else "Balance sheet") + _conv_suffix(r)
        blocks = []
        for key, head in (("assets", "Assets"), ("liabilities", "Liabilities"), ("equity", "Equity")):
            sec = r[key]
            b = [[head, ""]]
            b += [["  " + a["account"], _t(a["balance"])] for a in sec["accounts"]]
            if key == "equity":
                b += [["  Retained earnings", _t(m)] for m in sec.get("retained_earnings", [])]
            b += [["Total " + key, _t(m)] for m in sec["total"]]
            blocks.append(b)
        table = render_table(["Account", "Balance"], _blocks(blocks, 2), "lr")
    elif kind == "income_statement":
        title = "Income statement %s to %s" % (r["start"], r["end"]) + _conv_suffix(r)
        blocks = []
        for key, head in (("income", "Income"), ("expenses", "Expenses")):
            sec = r[key]
            b = [[head, "", ""]]
            b += [["  " + a["account"], _t(a["amount"]), a["percent"] + "%"] for a in sec["accounts"]]
            b += [["Total " + key, _t(m), ""] for m in sec["total"]]
            blocks.append(b)
        blocks.append([["Net income", _t(m), ""] for m in r["net"]])
        table = render_table(["Account", "Amount", "Percent"], _blocks(blocks, 3), "lrr")
    elif kind == "cashflow":
        title = "Cash flow %s to %s" % (r["start"], r["end"])
        blocks = [[["Opening balance", _t(m)] for m in r["opening"]]]
        b = [["Money in", ""]] + [["  " + a["account"], _t(a["amount"])] for a in r["inflows"]]
        b += [["Total money in", _t(m)] for m in r["total_in"]]
        blocks.append(b)
        b = [["Money out", ""]] + [["  " + a["account"], _t(a["amount"])] for a in r["outflows"]]
        b += [["Total money out", _t(m)] for m in r["total_out"]]
        blocks.append(b)
        blocks.append([["Net change", _t(m)] for m in r["net"]] + [["Closing balance", _t(m)] for m in r["closing"]])
        table = render_table(["Account", "Amount"], _blocks(blocks, 2), "lr")
    elif kind == "net_worth":
        title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
        rows = []
        for p in r["points"]:
            if not p["assets"]:
                rows.append([p["date"], "", "", ""])
            for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
                rows.append([p["date"], _t(a), _t(l), _t(n)])
        table = render_table(["Date", "Assets", "Liabilities", "Net"], rows, "lrrr")
    else:
        title = "Register %s" % r["account"]
        if r.get("rollup"):
            title += " (with sub-accounts)"
        if r.get("start"):
            title += " %s to %s" % (r["start"], r["end"])
        rows = [["", "", "Opening balance", "", "", _t(m)] for m in r["opening"]]
        rows += [[x["date"], "" if x["id"] is None else x["id"], x["payee"], x["account"], _t(x["amount"]),
                  _t(x["balance"])] for x in r["rows"]]
        rows += [["", "", "Closing balance", "", "", _t(m)] for m in r["closing"]]
        table = render_table(["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr")
    return title + "\n\n" + table


# -- CSV ------------------------------------------------------------------------

def _a(money):
    return (None, None) if money is None else (money["currency"], money["amount"])


def report_to_csv(report):
    kind = _check(report)
    try:
        return _csv(kind, report)
    except ReportError:
        raise
    except (KeyError, TypeError, IndexError, AttributeError, ValueError) as e:
        raise ReportError("malformed report: %s" % e) from None


def _csv(kind, r):
    if kind == "trial_balance":
        rows = []
        for a in r["accounts"]:
            m = a["debit"] or a["credit"]
            rows.append([a["account"], a["type"], m["currency"],
                         a["debit"]["amount"] if a["debit"] else None,
                         a["credit"]["amount"] if a["credit"] else None])
        return to_csv(["account", "type", "currency", "debit", "credit"], rows)
    if kind == "balance_sheet":
        rows = []
        for key in ("assets", "liabilities", "equity"):
            for a in r[key]["accounts"]:
                rows.append([key, a["account"], a["balance"]["currency"], a["balance"]["amount"]])
        for m in r["equity"].get("retained_earnings", []):
            rows.append(["equity", "Retained earnings", m["currency"], m["amount"]])
        return to_csv(["section", "account", "currency", "balance"], rows)
    if kind == "income_statement":
        rows = []
        for key in ("income", "expenses"):
            for a in r[key]["accounts"]:
                rows.append([key, a["account"], a["amount"]["currency"], a["amount"]["amount"], a["percent"]])
        return to_csv(["section", "account", "currency", "amount", "percent"], rows)
    if kind == "cashflow":
        rows = [["opening", "", m["currency"], m["amount"]] for m in r["opening"]]
        rows += [["in", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["inflows"]]
        rows += [["out", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["outflows"]]
        rows += [["closing", "", m["currency"], m["amount"]] for m in r["closing"]]
        return to_csv(["section", "account", "currency", "amount"], rows)
    if kind == "register":
        rows = [[x["date"], x["id"], x["payee"], x["narration"], x["account"], x["amount"]["currency"],
                 x["amount"]["amount"], x["balance"]["amount"]] for x in r["rows"]]
        return to_csv(["date", "id", "payee", "narration", "account", "currency", "amount", "balance"], rows)
    rows = []
    for p in r["points"]:
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], a["currency"], a["amount"], l["amount"], n["amount"]])
    return to_csv(["date", "currency", "assets", "liabilities", "net"], rows)

"""CSV and JSON export, and fixed-width text tables."""

import json
from datetime import date

from tallybook.currency import CurrencyError
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import ValidationError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, MoneyError


class ExportError(ValidationError):
    """A table or document that cannot be written or read."""


# -- CSV ----------------------------------------------------------------------

def _csv_field(value):
    text = "" if value is None else str(value)
    if any(c in text for c in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def to_csv(headers, rows):
    lines = [",".join(_csv_field(h) for h in headers)]
    for row in rows:
        lines.append(",".join(_csv_field(c) for c in row))
    return "".join(line + "\n" for line in lines)


CSV_HEADERS = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


def transactions_to_csv(txs):
    rows = []
    for tx in txs:
        head = [tx.id, format_date(tx.date), tx.flag, tx.payee, tx.narration, ";".join(sorted(set(tx.tags)))]
        if not tx.postings:
            rows.append(head + [None, None, None, None])
        for p in tx.postings:
            if p.amount is None:
                rows.append(head + [p.account, None, None, p.note])
            else:
                rows.append(head + [p.account, p.amount.amount_str(), p.amount.currency, p.note])
    return to_csv(CSV_HEADERS, rows)


# -- JSON ---------------------------------------------------------------------

def to_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def money_to_dict(money):
    if money is None:
        return None
    return {"amount": money.amount_str(), "currency": money.currency}


def posting_to_dict(p):
    return {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}


def transaction_to_dict(tx):
    return {
        "id": tx.id,
        "date": format_date(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": sorted(set(tx.tags)),
        "postings": [posting_to_dict(p) for p in tx.postings],
    }


def transactions_to_json(txs):
    return to_json([transaction_to_dict(tx) for tx in txs])


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def money_from_obj(obj, where):
    if not isinstance(obj, dict) or set(obj) != {"amount", "currency"}:
        raise ExportError("%s: amount must be null or an object with amount and currency" % where)
    if not isinstance(obj["amount"], str) or not isinstance(obj["currency"], str):
        raise ExportError("%s: amount and currency must be text" % where)
    try:
        return Money.of(obj["amount"], obj["currency"])
    except (MoneyError, CurrencyError) as e:
        raise ExportError("%s: %s" % (where, e.message)) from None


def transactions_from_json(text):
    try:
        data = json.loads(text)
    except (ValueError, TypeError) as e:
        raise ExportError("not valid JSON: %s" % e) from None
    if not isinstance(data, list):
        raise ExportError("the JSON is not an array")
    out = []
    for n, item in enumerate(data, 1):
        where = "transaction %d" % n
        if not isinstance(item, dict):
            raise ExportError("%s: not an object" % where)
        for k in item:
            if k not in _TX_KEYS:
                raise ExportError("%s: unknown key %r" % (where, k))
        for k in ("date", "payee", "postings"):
            if k not in item:
                raise ExportError("%s: missing %s" % (where, k))
        d = item["date"]
        try:
            day = parse_date(d)
        except DateError:
            raise ExportError("%s: invalid date %r" % (where, d)) from None
        tid = item.get("id")
        if tid is not None and (not isinstance(tid, int) or isinstance(tid, bool) or tid < 1):
            raise ExportError("%s: invalid id %r" % (where, tid))
        flag = item.get("flag", "*")
        if flag not in ("*", "!") or not isinstance(flag, str):
            raise ExportError("%s: invalid flag %r" % (where, flag))
        payee = item["payee"]
        if not isinstance(payee, str):
            raise ExportError("%s: payee must be text" % where)
        narration = item.get("narration", "")
        if not isinstance(narration, str):
            raise ExportError("%s: narration must be text" % where)
        tags = item.get("tags", [])
        if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
            raise ExportError("%s: tags must be a list of text" % where)
        postings_in = item["postings"]
        if not isinstance(postings_in, list):
            raise ExportError("%s: postings must be a list" % where)
        postings = []
        for m, p in enumerate(postings_in, 1):
            pw = "%s posting %d" % (where, m)
            if not isinstance(p, dict):
                raise ExportError("%s: not an object" % pw)
            for k in p:
                if k not in _POSTING_KEYS:
                    raise ExportError("%s: unknown key %r" % (pw, k))
            if "account" not in p or not isinstance(p["account"], str):
                raise ExportError("%s: account missing or not text" % pw)
            note = p.get("note", "")
            if not isinstance(note, str):
                raise ExportError("%s: note must be text" % pw)
            amt = p.get("amount")
            money = None if amt is None else money_from_obj(amt, pw)
            postings.append(Posting(p["account"], money, note))
        out.append(Transaction(day, payee, narration, postings, tuple(sorted(set(tags))), flag, tid))
    return out


# -- tables -------------------------------------------------------------------

def _cell(value):
    text = "" if value is None else str(value)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    headers = [_cell(h) for h in headers]
    if not headers:
        return ""
    n = len(headers)
    if align is None:
        align = ["l"] * n
    else:
        if not isinstance(align, (str, list, tuple)):
            raise ExportError("align must be a string or list of l/r letters")
        align = list(align)
        if len(align) != n or any(a not in ("l", "r") for a in align):
            raise ExportError("align must have one 'l' or 'r' per column")
    table = []
    for row in rows:
        cells = [_cell(c) for c in row]
        if len(cells) != n:
            raise ExportError("a row has %d cells, expected %d" % (len(cells), n))
        table.append(cells)
    widths = [max([len(headers[i])] + [len(r[i]) for r in table]) for i in range(n)]

    def line(cells):
        parts = [c.ljust(w) if a == "l" else c.rjust(w) for c, w, a in zip(cells, widths, align)]
        return "  ".join(parts).rstrip(" ")

    out = [line(headers), line(["-" * w for w in widths])]
    out += [line(r) for r in table]
    return "".join(l + "\n" for l in out)

"""Reports over a ledger, as plain dicts, text and CSV."""

from datetime import date, timedelta

from tallybook.accounts import ROOT_TYPES
from tallybook.budgets import percent_text
from tallybook.currency import currency as _currency
from tallybook.dates import DateError, Period, format_date, periods
from tallybook.errors import ValidationError
from tallybook.export import render_table, to_csv
from tallybook.money import Money, format_minor


class ReportError(ValidationError):
    """A report that cannot be made."""


REPORTS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")


def _m(minor, cur):
    return {"amount": format_minor(minor, cur), "currency": cur}


def _mm(money):
    return _m(money.minor, money.currency)


def _type(path):
    return ROOT_TYPES.get(path.split(":")[0])


def _fd(d):
    return None if d is None else format_date(d)


def _postings(ledger, start=None, end=None):
    for tx in ledger.transactions():
        if start is not None and tx.date < start:
            continue
        if end is not None and tx.date > end:
            continue
        for p in tx.postings:
            if p.amount is not None:
                yield tx, p


def _sums(ledger, start=None, end=None):
    """{(account, currency): minor} of postings in the date range."""
    out = {}
    for _tx, p in _postings(ledger, start, end):
        k = (p.account, p.amount.currency)
        out[k] = out.get(k, 0) + p.amount.minor
    return out


def _add(d, cur, v):
    d[cur] = d.get(cur, 0) + v


def _money_list(d, keep_zero=False):
    return [_m(v, c) for c, v in sorted(d.items()) if keep_zero or v != 0]


# -- trial balance --------------------------------------------------------------

def trial_balance(ledger, as_of=None):
    sums = _sums(ledger, end=as_of)
    accounts = []
    totals = {}
    for (acct, cur), v in sorted(sums.items()):
        if v == 0:
            continue
        t = totals.setdefault(cur, [0, 0])
        if v > 0:
            accounts.append({"account": acct, "type": _type(acct), "debit": _m(v, cur), "credit": None})
            t[0] += v
        else:
            accounts.append({"account": acct, "type": _type(acct), "debit": None, "credit": _m(-v, cur)})
            t[1] += -v
    return {
        "report": "trial_balance",
        "as_of": _fd(as_of),
        "accounts": accounts,
        "totals": [{"currency": c, "debit": _m(d, c), "credit": _m(cr, c), "balanced": d == cr}
                   for c, (d, cr) in sorted(totals.items())],
    }


# -- balance sheet --------------------------------------------------------------

def _convert(ledger, minor, cur, target, on):
    if cur == target:
        return minor
    return ledger.rates.convert(Money(minor, cur), target, on).minor


def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    if convert_to is not None:
        _currency(convert_to)
        if as_of is None:
            raise ReportError("converting a balance sheet needs an as-of date")
    sums = _sums(ledger, end=as_of)
    sections = {"asset": [], "liability": [], "equity": []}
    retained = {}
    for (acct, cur), v in sorted(sums.items()):
        t = _type(acct)
        if t in ("income", "expense"):
            _add(retained, cur, -v)
            continue
        if t not in sections or v == 0:
            continue
        sections[t].append((acct, cur, v if t == "asset" else -v))
    retained = {c: v for c, v in retained.items() if v != 0}
    out = {"report": "balance_sheet", "as_of": _fd(as_of), "currency": convert_to}
    totals = {}
    for key, name in (("asset", "assets"), ("liability", "liabilities"), ("equity", "equity")):
        lines = []
        tot = {}
        for acct, cur, v in sections[key]:
            if convert_to is None:
                lines.append({"account": acct, "balance": _m(v, cur)})
                _add(tot, cur, v)
            else:
                cv = _convert(ledger, v, cur, convert_to, as_of)
                lines.append({"account": acct, "balance": _m(cv, convert_to), "original": _m(v, cur)})
                _add(tot, convert_to, cv)
        sec = {"accounts": lines}
        if key == "equity":
            if convert_to is None:
                sec["retained_earnings"] = _money_list(retained)
                for c, v in retained.items():
                    _add(tot, c, v)
            else:
                if retained:
                    rv = sum(_convert(ledger, v, c, convert_to, as_of) for c, v in sorted(retained.items()))
                    sec["retained_earnings"] = [_m(rv, convert_to)]
                    _add(tot, convert_to, rv)
                else:
                    sec["retained_earnings"] = []
        if convert_to is not None:
            tot.setdefault(convert_to, 0)
        sec["total"] = _money_list(tot, keep_zero=True)
        totals[key] = tot
        out[name] = sec
    curs = set(totals["asset"]) | set(totals["liability"]) | set(totals["equity"])
    out["balanced"] = all(totals["asset"].get(c, 0) == totals["liability"].get(c, 0) + totals["equity"].get(c, 0)
                          for c in curs)
    return out


# -- income statement -----------------------------------------------------------

def income_statement(ledger, period, convert_to=None):
    if convert_to is not None:
        _currency(convert_to)
    sums = _sums(ledger, period.start, period.end)
    out = {"report": "income_statement", "start": _fd(period.start), "end": _fd(period.end),
           "currency": convert_to}
    totals = {}
    for key, name in (("income", "income"), ("expense", "expenses")):
        raw = []
        for (acct, cur), v in sorted(sums.items()):
            if _type(acct) != key or v == 0:
                continue
            raw.append((acct, cur, -v if key == "income" else v))
        tot = {}
        shown = []
        for acct, cur, v in raw:
            if convert_to is None:
                shown.append((acct, cur, v, None))
                _add(tot, cur, v)
            else:
                cv = _convert(ledger, v, cur, convert_to, period.end)
                shown.append((acct, convert_to, cv, (v, cur)))
                _add(tot, convert_to, cv)
        if convert_to is not None:
            tot.setdefault(convert_to, 0)
        lines = []
        for acct, cur, v, orig in shown:
            total = tot.get(cur, 0)
            line = {"account": acct, "amount": _m(v, cur),
                    "percent": "0.0" if total == 0 else percent_text(v, total)}
            if orig is not None:
                line["original"] = _m(orig[0], orig[1])
            lines.append(line)
        totals[key] = tot
        out[name] = {"accounts": lines, "total": _money_list(tot, keep_zero=True)}
    net = {}
    for c in set(totals["income"]) | set(totals["expense"]):
        net[c] = totals["income"].get(c, 0) - totals["expense"].get(c, 0)
    out["net"] = _money_list(net, keep_zero=True)
    return out


# -- cash flow ------------------------------------------------------------------

def _asset_balance(ledger, end, before=False):
    out = {}
    for tx, p in _postings(ledger):
        if (tx.date >= end) if before else (tx.date > end):
            continue
        if _type(p.account) == "asset":
            _add(out, p.amount.currency, p.amount.minor)
    return out


def cashflow(ledger, period):
    contrib = {}
    for tx in ledger.transactions():
        if not (period.start <= tx.date <= period.end):
            continue
        asset_sum = {}
        for p in tx.postings:
            if p.amount is not None and _type(p.account) == "asset":
                _add(asset_sum, p.amount.currency, p.amount.minor)
        for p in tx.postings:
            if p.amount is None or _type(p.account) == "asset":
                continue
            if asset_sum.get(p.amount.currency, 0) == 0:
                continue
            k = (p.account, p.amount.currency)
            contrib[k] = contrib.get(k, 0) - p.amount.minor
    currencies = set()
    for tx, p in _postings(ledger, end=period.end):
        if _type(p.account) == "asset":
            currencies.add(p.amount.currency)
    opening = _asset_balance(ledger, period.start, before=True)
    closing = _asset_balance(ledger, period.end)
    inflows, outflows = [], []
    t_in = {c: 0 for c in currencies}
    t_out = {c: 0 for c in currencies}
    for (acct, cur), v in sorted(contrib.items()):
        if v > 0:
            inflows.append({"account": acct, "amount": _m(v, cur)})
            _add(t_in, cur, v)
        elif v < 0:
            outflows.append({"account": acct, "amount": _m(-v, cur)})
            _add(t_out, cur, -v)
    cs = sorted(currencies | set(t_in) | set(t_out))
    return {
        "report": "cashflow", "start": _fd(period.start), "end": _fd(period.end),
        "opening": [_m(opening.get(c, 0), c) for c in cs],
        "inflows": inflows, "outflows": outflows,
        "total_in": [_m(t_in.get(c, 0), c) for c in cs],
        "total_out": [_m(t_out.get(c, 0), c) for c in cs],
        "net": [_m(t_in.get(c, 0) - t_out.get(c, 0), c) for c in cs],
        "closing": [_m(closing.get(c, 0), c) for c in cs],
    }


# -- register -------------------------------------------------------------------

def register(ledger, account, period=None, rollup=False):
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account: %s" % (account,))

    def selected(path):
        return path == account or (rollup and path.startswith(account + ":"))

    start = period.start if period is not None else None
    end = period.end if period is not None else None
    opening = {}
    currencies = set()
    rows = []
    running = None
    items = []
    for tx in ledger.transactions():
        for p in tx.postings:
            if p.amount is None or not selected(p.account):
                continue
            if end is not None and tx.date > end:
                continue
            currencies.add(p.amount.currency)
            if start is not None and tx.date < start:
                _add(opening, p.amount.currency, p.amount.minor)
            else:
                items.append((tx, p))
    running = dict(opening)
    for tx, p in items:
        cur = p.amount.currency
        _add(running, cur, p.amount.minor)
        rows.append({"date": _fd(tx.date), "id": tx.id, "payee": tx.payee, "narration": tx.narration,
                     "account": p.account, "amount": _m(p.amount.minor, cur), "balance": _m(running[cur], cur)})
    cs = sorted(currencies)
    return {
        "report": "register", "account": account, "rollup": bool(rollup),
        "start": _fd(start), "end": _fd(end),
        "opening": [_m(opening.get(c, 0), c) for c in cs],
        "rows": rows,
        "closing": [_m(running.get(c, 0), c) for c in cs],
    }


# -- net worth ------------------------------------------------------------------

def net_worth(ledger, period, step="month"):
    if not isinstance(step, str) or step not in ("week", "month", "quarter", "year"):
        raise ReportError("invalid step %r: expected week, month, quarter or year" % (step,))
    try:
        steps = periods(period.start, period.end, step)
    except DateError as e:
        raise ReportError(e.message) from None
    points = []
    all_postings = list(_postings(ledger))
    for p in steps:
        d = p.end
        assets, liabs = {}, {}
        for tx, ps in all_postings:
            if tx.date > d:
                continue
            t = _type(ps.account)
            if t == "asset":
                _add(assets, ps.amount.currency, ps.amount.minor)
                liabs.setdefault(ps.amount.currency, 0)
            elif t == "liability":
                _add(liabs, ps.amount.currency, -ps.amount.minor)
                assets.setdefault(ps.amount.currency, 0)
        cs = sorted(assets)
        points.append({"date": _fd(d),
                       "assets": [_m(assets[c], c) for c in cs],
                       "liabilities": [_m(liabs[c], c) for c in cs],
                       "net": [_m(assets[c] - liabs[c], c) for c in cs]})
    return {"report": "net_worth", "start": _fd(period.start), "end": _fd(period.end), "step": step,
            "points": points}


# -- text -----------------------------------------------------------------------

def _check(report):
    if not isinstance(report, dict) or report.get("report") not in REPORTS:
        raise ReportError("not a report")
    return report["report"]


def _t(money):
    if money is None:
        return ""
    return "%s %s" % (money["amount"], money["currency"])


def _blocks(blocks, width):
    rows = []
    for b in blocks:
        if not b:
            continue
        if rows:
            rows.append([""] * width)
        rows.extend(b)
    return rows


def render_text(report):
    kind = _check(report)
    try:
        return _render(kind, report)
    except ReportError:
        raise
    except (KeyError, TypeError, IndexError, AttributeError, ValueError) as e:
        raise ReportError("malformed report: %s" % e) from None


def _conv_suffix(report):
    return " (in %s)" % report["currency"] if report.get("currency") else ""


def _render(kind, r):
    if kind == "trial_balance":
        title = "Trial balance as of %s" % r["as_of"] if r["as_of"] else "Trial balance"
        rows = [[a["account"], a["type"] or "", _t(a["debit"]), _t(a["credit"])] for a in r["accounts"]]
        rows += [["Total", "", _t(t["debit"]), _t(t["credit"])] for t in r["totals"]]
        table = render_table(["Account", "Type", "Debit", "Credit"], rows, "llrr")
    elif kind == "balance_sheet":
        title = ("Balance sheet as of %s" % r["as_of"] if r["as_of"] else "Balance sheet") + _conv_suffix(r)
        blocks = []
        for key, head in (("assets", "Assets"), ("liabilities", "Liabilities"), ("equity", "Equity")):
            sec = r[key]
            b = [[head, ""]]
            b += [["  " + a["account"], _t(a["balance"])] for a in sec["accounts"]]
            if key == "equity":
                b += [["  Retained earnings", _t(m)] for m in sec.get("retained_earnings", [])]
            b += [["Total " + key, _t(m)] for m in sec["total"]]
            blocks.append(b)
        table = render_table(["Account", "Balance"], _blocks(blocks, 2), "lr")
    elif kind == "income_statement":
        title = "Income statement %s to %s" % (r["start"], r["end"]) + _conv_suffix(r)
        blocks = []
        for key, head in (("income", "Income"), ("expenses", "Expenses")):
            sec = r[key]
            b = [[head, "", ""]]
            b += [["  " + a["account"], _t(a["amount"]), a["percent"] + "%"] for a in sec["accounts"]]
            b += [["Total " + key, _t(m), ""] for m in sec["total"]]
            blocks.append(b)
        blocks.append([["Net income", _t(m), ""] for m in r["net"]])
        table = render_table(["Account", "Amount", "Percent"], _blocks(blocks, 3), "lrr")
    elif kind == "cashflow":
        title = "Cash flow %s to %s" % (r["start"], r["end"])
        blocks = [[["Opening balance", _t(m)] for m in r["opening"]]]
        b = [["Money in", ""]] + [["  " + a["account"], _t(a["amount"])] for a in r["inflows"]]
        b += [["Total money in", _t(m)] for m in r["total_in"]]
        blocks.append(b)
        b = [["Money out", ""]] + [["  " + a["account"], _t(a["amount"])] for a in r["outflows"]]
        b += [["Total money out", _t(m)] for m in r["total_out"]]
        blocks.append(b)
        blocks.append([["Net change", _t(m)] for m in r["net"]] + [["Closing balance", _t(m)] for m in r["closing"]])
        table = render_table(["Account", "Amount"], _blocks(blocks, 2), "lr")
    elif kind == "net_worth":
        title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
        rows = []
        for p in r["points"]:
            if not p["assets"]:
                rows.append([p["date"], "", "", ""])
            for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
                rows.append([p["date"], _t(a), _t(l), _t(n)])
        table = render_table(["Date", "Assets", "Liabilities", "Net"], rows, "lrrr")
    else:
        title = "Register %s" % r["account"]
        if r.get("rollup"):
            title += " (with sub-accounts)"
        if r.get("start"):
            title += " %s to %s" % (r["start"], r["end"])
        rows = [["", "", "Opening balance", "", "", _t(m)] for m in r["opening"]]
        rows += [[x["date"], "" if x["id"] is None else x["id"], x["payee"], x["account"], _t(x["amount"]),
                  _t(x["balance"])] for x in r["rows"]]
        rows += [["", "", "Closing balance", "", "", _t(m)] for m in r["closing"]]
        table = render_table(["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr")
    return title + "\n\n" + table


# -- CSV ------------------------------------------------------------------------

def _a(money):
    return (None, None) if money is None else (money["currency"], money["amount"])


def report_to_csv(report):
    kind = _check(report)
    try:
        return _csv(kind, report)
    except ReportError:
        raise
    except (KeyError, TypeError, IndexError, AttributeError, ValueError) as e:
        raise ReportError("malformed report: %s" % e) from None


def _csv(kind, r):
    if kind == "trial_balance":
        rows = []
        for a in r["accounts"]:
            m = a["debit"] or a["credit"]
            rows.append([a["account"], a["type"], m["currency"],
                         a["debit"]["amount"] if a["debit"] else None,
                         a["credit"]["amount"] if a["credit"] else None])
        return to_csv(["account", "type", "currency", "debit", "credit"], rows)
    if kind == "balance_sheet":
        rows = []
        for key in ("assets", "liabilities", "equity"):
            for a in r[key]["accounts"]:
                rows.append([key, a["account"], a["balance"]["currency"], a["balance"]["amount"]])
        for m in r["equity"].get("retained_earnings", []):
            rows.append(["equity", "Retained earnings", m["currency"], m["amount"]])
        return to_csv(["section", "account", "currency", "balance"], rows)
    if kind == "income_statement":
        rows = []
        for key in ("income", "expenses"):
            for a in r[key]["accounts"]:
                rows.append([key, a["account"], a["amount"]["currency"], a["amount"]["amount"], a["percent"]])
        return to_csv(["section", "account", "currency", "amount", "percent"], rows)
    if kind == "cashflow":
        rows = [["opening", "", m["currency"], m["amount"]] for m in r["opening"]]
        rows += [["in", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["inflows"]]
        rows += [["out", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["outflows"]]
        rows += [["closing", "", m["currency"], m["amount"]] for m in r["closing"]]
        return to_csv(["section", "account", "currency", "amount"], rows)
    if kind == "register":
        rows = [[x["date"], x["id"], x["payee"], x["narration"], x["account"], x["amount"]["currency"],
                 x["amount"]["amount"], x["balance"]["amount"]] for x in r["rows"]]
        return to_csv(["date", "id", "payee", "narration", "account", "currency", "amount", "balance"], rows)
    rows = []
    for p in r["points"]:
        for a, l, n in zip(p["assets"], p["liabilities"], p["net"]):
            rows.append([p["date"], a["currency"], a["amount"], l["amount"], n["amount"]])
    return to_csv(["date", "currency", "assets", "liabilities", "net"], rows)
